### 2. Date Extensions 구현

**Date+Extensions.swift**
```swift
import Foundation

public extension Date {
    // MARK: - ISO8601 포매팅 (서버 통신용)

    /// ISO8601 문자열로 변환 (UTC, RFC3339 형식)
    /// 예: "2025-11-27T12:34:56.789Z"
    var iso8601String: String {
        ISO8601DateFormatter.shared.string(from: self)
    }

    /// ISO8601 문자열에서 Date 생성
    /// - Parameter string: ISO8601 형식 문자열
    /// - Returns: Date 또는 nil
    static func from(iso8601: String) -> Date? {
        ISO8601DateFormatter.shared.date(from: iso8601)
    }

    // MARK: - 상대 시간 표현 (UI용)

    /// 현재 시간 기준 상대적 표현
    /// 예: "방금 전", "5분 전", "어제", "3일 전"
    func relativeString(from referenceDate: Date = Date()) -> String {
        let formatter = RelativeDateTimeFormatter()
        formatter.unitsStyle = .full
        formatter.locale = Locale(identifier: "ko_KR")
        return formatter.localizedString(for: self, relativeTo: referenceDate)
    }

    /// 짧은 상대 시간 표현
    /// 예: "5분", "2시간", "3일"
    func shortRelativeString(from referenceDate: Date = Date()) -> String {
        let formatter = RelativeDateTimeFormatter()
        formatter.unitsStyle = .short
        formatter.locale = Locale(identifier: "ko_KR")
        return formatter.localizedString(for: self, relativeTo: referenceDate)
    }

    // MARK: - 날짜 비교

    /// 같은 날인지 확인
    func isSameDay(as other: Date, calendar: Calendar = .current) -> Bool {
        calendar.isDate(self, inSameDayAs: other)
    }

    /// 오늘인지 확인
    var isToday: Bool {
        Calendar.current.isDateInToday(self)
    }

    /// 어제인지 확인
    var isYesterday: Bool {
        Calendar.current.isDateInYesterday(self)
    }

    /// 이번 주인지 확인
    var isThisWeek: Bool {
        Calendar.current.isDate(self, equalTo: Date(), toGranularity: .weekOfYear)
    }

    // MARK: - 날짜 조작

    /// 하루의 시작 시간 (00:00:00)
    var startOfDay: Date {
        Calendar.current.startOfDay(for: self)
    }

    /// 하루의 끝 시간 (23:59:59)
    var endOfDay: Date {
        Calendar.current.date(bySettingHour: 23, minute: 59, second: 59, of: self) ?? self
    }

    /// 일주일의 시작일 (월요일)
    var startOfWeek: Date {
        var calendar = Calendar.current
        calendar.firstWeekday = 2 // 월요일
        return calendar.dateInterval(of: .weekOfYear, for: self)?.start ?? self
    }

    /// 월의 시작일
    var startOfMonth: Date {
        Calendar.current.dateInterval(of: .month, for: self)?.start ?? self
    }

    /// N일 추가/감소
    func adding(days: Int) -> Date {
        Calendar.current.date(byAdding: .day, value: days, to: self) ?? self
    }

    /// N시간 추가/감소
    func adding(hours: Int) -> Date {
        Calendar.current.date(byAdding: .hour, value: hours, to: self) ?? self
    }

    /// N분 추가/감소
    func adding(minutes: Int) -> Date {
        Calendar.current.date(byAdding: .minute, value: minutes, to: self) ?? self
    }

    // MARK: - 체크인 간격 검증 (서버 로직 일치)

    /// 15/30/45/120분 간격 검증
    /// - Parameter lastCheckin: 마지막 체크인 시간
    /// - Returns: (허용 여부, 남은 대기 시간)
    func isValidCheckinInterval(since lastCheckin: Date) -> (isValid: Bool, remainingWaitTime: TimeInterval?) {
        let elapsed = self.timeIntervalSince(lastCheckin)
        let minutes = Int(elapsed / 60)

        // 서버 로직: 처음 2시간은 15/30/45분, 이후 120분
        if elapsed < 7200 { // 2시간 미만
            let validIntervals = [15, 30, 45]
            if validIntervals.contains(minutes) {
                return (true, nil)
            } else {
                // 다음 허용 간격까지 남은 시간 계산
                let nextValid = validIntervals.first { $0 > minutes } ?? 120
                let nextAllowedTime = lastCheckin.adding(minutes: nextValid)
                let remaining = nextAllowedTime.timeIntervalSince(self)
                return (false, remaining)
            }
        } else { // 2시간 이상
            if minutes % 120 == 0 {
                return (true, nil)
            } else {
                let nextMultiple = ((minutes / 120) + 1) * 120
                let nextAllowedTime = lastCheckin.adding(minutes: nextMultiple)
                let remaining = nextAllowedTime.timeIntervalSince(self)
                return (false, remaining)
            }
        }
    }
}

// MARK: - Private Helpers

private extension ISO8601DateFormatter {
    static let shared: ISO8601DateFormatter = {
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        return formatter
    }()
}
```

