### 3. String Extensions 구현

**String+Extensions.swift**
```swift
import Foundation

public extension String {
    // MARK: - 유효성 검증

    /// 이메일 형식 검증
    var isValidEmail: Bool {
        let emailRegex = "[A-Z0-9a-z._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,64}"
        let predicate = NSPredicate(format: "SELF MATCHES %@", emailRegex)
        return predicate.evaluate(with: self)
    }

    /// 비밀번호 강도 검증 (최소 8자, 영문+숫자+특수문자)
    var isStrongPassword: Bool {
        guard count >= 8 else { return false }
        let hasUppercase = rangeOfCharacter(from: .uppercaseLetters) != nil
        let hasLowercase = rangeOfCharacter(from: .lowercaseLetters) != nil
        let hasDigit = rangeOfCharacter(from: .decimalDigits) != nil
        let hasSpecial = rangeOfCharacter(from: CharacterSet(charactersIn: "!@#$%^&*()_+-=[]{}|;:,.<>?")) != nil
        return hasUppercase && hasLowercase && hasDigit && hasSpecial
    }

    /// 빈 문자열 또는 공백만 있는지 확인
    var isBlank: Bool {
        trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    // MARK: - 문자열 조작

    /// 앞뒤 공백 제거
    var trimmed: String {
        trimmingCharacters(in: .whitespacesAndNewlines)
    }

    /// 최대 길이로 자르기 (말줄임표 추가)
    func truncated(to maxLength: Int, trailing: String = "...") -> String {
        guard count > maxLength else { return self }
        let endIndex = index(startIndex, offsetBy: maxLength)
        return String(self[..<endIndex]) + trailing
    }

    /// 문자 개수 (이모지 고려)
    var characterCount: Int {
        count
    }

    // MARK: - URL 처리

    /// URL 인코딩
    var urlEncoded: String? {
        addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed)
    }

    /// Base64 인코딩
    var base64Encoded: String {
        Data(utf8).base64EncodedString()
    }

    /// Base64 디코딩
    var base64Decoded: String? {
        guard let data = Data(base64Encoded: self) else { return nil }
        return String(data: data, encoding: .utf8)
    }

    // MARK: - 로컬라이제이션

    /// 현지화된 문자열 반환
    var localized: String {
        NSLocalizedString(self, comment: "")
    }

    /// 포맷팅된 현지화 문자열
    func localized(with arguments: CVarArg...) -> String {
        String(format: NSLocalizedString(self, comment: ""), arguments: arguments)
    }
}

// MARK: - 숫자 변환

public extension String {
    /// Int로 변환 (옵셔널)
    var toInt: Int? {
        Int(self)
    }

    /// Double로 변환 (옵셔널)
    var toDouble: Double? {
        Double(self)
    }

    /// Bool로 변환 ("true", "1", "yes" → true)
    var toBool: Bool? {
        switch lowercased() {
        case "true", "1", "yes": return true
        case "false", "0", "no": return false
        default: return nil
        }
    }
}
```

