### 5. AppError Enum 구현

**AppError.swift**
```swift
import Foundation

/// 앱 전역 에러 타입
public enum AppError: LocalizedError {
    // MARK: - 네트워크 에러
    case networkError(underlying: Error)
    case noInternetConnection
    case timeout
    case serverError(statusCode: Int, message: String?)
    case invalidResponse
    case decodingError(underlying: Error)

    // MARK: - 인증 에러
    case unauthorized
    case tokenExpired
    case invalidCredentials
    case twoFactorRequired

    // MARK: - 유효성 검증 에러
    case invalidEmail
    case weakPassword
    case invalidCheckinInterval(remainingSeconds: Int)
    case contentTooLong(maxLength: Int)
    case requiredFieldMissing(field: String)

    // MARK: - 데이터 에러
    case notFound(resource: String)
    case alreadyExists(resource: String)
    case syncConflict
    case dataCorrupted

    // MARK: - 권한 에러
    case permissionDenied(permission: String)
    case subscriptionRequired(feature: String)

    // MARK: - 기타
    case unknown(underlying: Error)
    case custom(message: String)

    // MARK: - LocalizedError 구현

    public var errorDescription: String? {
        switch self {
        case .networkError(let error):
            return "네트워크 오류: \(error.localizedDescription)"
        case .noInternetConnection:
            return "인터넷 연결이 없습니다"
        case .timeout:
            return "요청 시간이 초과되었습니다"
        case .serverError(let code, let message):
            return message ?? "서버 오류 (코드: \(code))"
        case .invalidResponse:
            return "잘못된 서버 응답입니다"
        case .decodingError:
            return "데이터 파싱 오류"

        case .unauthorized:
            return "로그인이 필요합니다"
        case .tokenExpired:
            return "세션이 만료되었습니다. 다시 로그인해주세요"
        case .invalidCredentials:
            return "이메일 또는 비밀번호가 올바르지 않습니다"
        case .twoFactorRequired:
            return "2단계 인증이 필요합니다"

        case .invalidEmail:
            return "유효하지 않은 이메일 형식입니다"
        case .weakPassword:
            return "비밀번호는 8자 이상, 영문+숫자+특수문자를 포함해야 합니다"
        case .invalidCheckinInterval(let seconds):
            return "체크인 간격이 올바르지 않습니다. \(seconds)초 후 다시 시도하세요"
        case .contentTooLong(let max):
            return "내용이 너무 깁니다 (최대 \(max)자)"
        case .requiredFieldMissing(let field):
            return "\(field) 항목은 필수입니다"

        case .notFound(let resource):
            return "\(resource)을(를) 찾을 수 없습니다"
        case .alreadyExists(let resource):
            return "\(resource)이(가) 이미 존재합니다"
        case .syncConflict:
            return "동기화 충돌이 발생했습니다"
        case .dataCorrupted:
            return "데이터가 손상되었습니다"

        case .permissionDenied(let permission):
            return "\(permission) 권한이 필요합니다"
        case .subscriptionRequired(let feature):
            return "\(feature) 기능은 프리미엄 구독이 필요합니다"

        case .unknown(let error):
            return "알 수 없는 오류: \(error.localizedDescription)"
        case .custom(let message):
            return message
        }
    }

    public var recoverySuggestion: String? {
        switch self {
        case .noInternetConnection:
            return "Wi-Fi 또는 모바일 데이터 연결을 확인해주세요"
        case .timeout:
            return "네트워크 연결 상태를 확인하고 다시 시도해주세요"
        case .unauthorized, .tokenExpired:
            return "다시 로그인해주세요"
        case .invalidCredentials:
            return "입력한 정보를 확인하고 다시 시도해주세요"
        case .invalidEmail:
            return "올바른 이메일 주소를 입력해주세요"
        case .weakPassword:
            return "더 강력한 비밀번호를 사용해주세요"
        case .subscriptionRequired:
            return "프리미엄 구독으로 업그레이드하세요"
        default:
            return "문제가 지속되면 고객 지원팀에 문의해주세요"
        }
    }

    /// HTTP 상태 코드 매핑
    public var httpStatusCode: Int? {
        switch self {
        case .unauthorized, .tokenExpired: return 401
        case .permissionDenied: return 403
        case .notFound: return 404
        case .alreadyExists, .syncConflict: return 409
        case .invalidCheckinInterval: return 429
        case .serverError(let code, _): return code
        default: return nil
        }
    }

    /// 재시도 가능 여부
    public var isRetryable: Bool {
        switch self {
        case .networkError, .timeout, .serverError(let code, _):
            return code >= 500
        default:
            return false
        }
    }
}
```

