### 6. Logger 구현 (OSLog)

**Logger.swift**
```swift
import OSLog

/// 앱 전역 로거
public final class AppLogger {
    public static let shared = AppLogger()

    private let subsystem = Bundle.main.bundleIdentifier ?? "com.donelist.app"

    // 카테고리별 Logger 인스턴스
    public let network: Logger
    public let auth: Logger
    public let checkin: Logger
    public let sync: Logger
    public let ui: Logger
    public let general: Logger

    private init() {
        network = Logger(subsystem: subsystem, category: "Network")
        auth = Logger(subsystem: subsystem, category: "Auth")
        checkin = Logger(subsystem: subsystem, category: "Checkin")
        sync = Logger(subsystem: subsystem, category: "Sync")
        ui = Logger(subsystem: subsystem, category: "UI")
        general = Logger(subsystem: subsystem, category: "General")
    }

    // MARK: - Convenience Methods

    /// 디버그 로그
    public static func debug(_ message: String, category: LogCategory = .general, file: String = #file, function: String = #function, line: Int = #line) {
        let logger = shared.logger(for: category)
        logger.debug("[\(fileName(from: file)):\(line)] \(function) - \(message)")
    }

    /// 정보 로그
    public static func info(_ message: String, category: LogCategory = .general) {
        let logger = shared.logger(for: category)
        logger.info("\(message)")
    }

    /// 경고 로그
    public static func warning(_ message: String, category: LogCategory = .general, file: String = #file, function: String = #function, line: Int = #line) {
        let logger = shared.logger(for: category)
        logger.warning("[\(fileName(from: file)):\(line)] \(function) - \(message)")
    }

    /// 에러 로그
    public static func error(_ message: String, error: Error? = nil, category: LogCategory = .general, file: String = #file, function: String = #function, line: Int = #line) {
        let logger = shared.logger(for: category)
        if let error = error {
            logger.error("[\(fileName(from: file)):\(line)] \(function) - \(message): \(error.localizedDescription)")
        } else {
            logger.error("[\(fileName(from: file)):\(line)] \(function) - \(message)")
        }
    }

    /// 치명적 에러 로그
    public static func critical(_ message: String, error: Error? = nil, category: LogCategory = .general, file: String = #file, function: String = #function, line: Int = #line) {
        let logger = shared.logger(for: category)
        if let error = error {
            logger.critical("[\(fileName(from: file)):\(line)] \(function) - \(message): \(error.localizedDescription)")
        } else {
            logger.critical("[\(fileName(from: file)):\(line)] \(function) - \(message)")
        }
    }

    // MARK: - Private Helpers

    private func logger(for category: LogCategory) -> Logger {
        switch category {
        case .network: return network
        case .auth: return auth
        case .checkin: return checkin
        case .sync: return sync
        case .ui: return ui
        case .general: return general
        }
    }

    private static func fileName(from filePath: String) -> String {
        (filePath as NSString).lastPathComponent
    }
}

// MARK: - Log Category

public enum LogCategory {
    case network
    case auth
    case checkin
    case sync
    case ui
    case general
}
```

