### 8. Configuration 구현

**Environment.swift**
```swift
import Foundation

/// 앱 실행 환경
public enum Environment {
    case development
    case staging
    case production

    /// 현재 환경 (빌드 설정 기반)
    public static var current: Environment {
        #if DEBUG
        return .development
        #elseif STAGING
        return .staging
        #else
        return .production
        #endif
    }

    /// 환경별 API Base URL
    public var apiBaseURL: String {
        switch self {
        case .development:
            return "http://localhost:8080"
