        let iso8601 = date.iso8601String
        XCTAssertTrue(iso8601.contains("2023-11-27T"))

        let parsedDate = Date.from(iso8601: iso8601)
        XCTAssertNotNil(parsedDate)
        XCTAssertEqual(date.timeIntervalSince1970, parsedDate!.timeIntervalSince1970, accuracy: 0.001)
    }

    func testRelativeStrings() {
        let now = Date()
        let fiveMinutesAgo = now.adding(minutes: -5)
        let relative = fiveMinutesAgo.relativeString(from: now)
        XCTAssertTrue(relative.contains("분") || relative.contains("전"))
    }

    func testDateComparisons() {
        let today = Date()
        XCTAssertTrue(today.isToday)
        XCTAssertFalse(today.isYesterday)

        let yesterday = today.adding(days: -1)
        XCTAssertTrue(yesterday.isYesterday)
        XCTAssertFalse(yesterday.isToday)
    }

    func testCheckinIntervalValidation() {
        let lastCheckin = Date()

        // 15분 후 - 유효
        let after15Min = lastCheckin.adding(minutes: 15)
        let result15 = after15Min.isValidCheckinInterval(since: lastCheckin)
        XCTAssertTrue(result15.isValid)
        XCTAssertNil(result15.remainingWaitTime)

        // 10분 후 - 무효 (15분 미만)
        let after10Min = lastCheckin.adding(minutes: 10)
        let result10 = after10Min.isValidCheckinInterval(since: lastCheckin)
        XCTAssertFalse(result10.isValid)
        XCTAssertNotNil(result10.remainingWaitTime)

