## 구현 세부사항

### 1. KeychainService 구현

**DLNetworking/Sources/Security/KeychainService.swift**
```swift
import Foundation
import Security

/// Keychain 저장소 래퍼
public final class KeychainService {
    enum KeychainError: Error {
        case unhandledError(status: OSStatus)
        case itemNotFound
        case unexpectedData
        case encodingError
        case decodingError
    }

    private let service: String

    public init(service: String = Bundle.main.bundleIdentifier ?? "com.donelist") {
        self.service = service
    }

    // MARK: - Generic Storage

    /// 문자열 저장
    func save(_ value: String, forKey key: String) throws {
        let data = Data(value.utf8)
        try save(data, forKey: key)
    }

    /// 데이터 저장
    func save(_ data: Data, forKey key: String) throws {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: key,
            kSecValueData as String: data,
            kSecAttrAccessible as String: kSecAttrAccessibleAfterFirstUnlock // 재부팅 후 첫 잠금 해제 시 접근 가능
        ]

        // 기존 항목 삭제
        SecItemDelete(query as CFDictionary)

        // 새 항목 추가
        let status = SecItemAdd(query as CFDictionary, nil)
        guard status == errSecSuccess else {
            throw KeychainError.unhandledError(status: status)
        }
    }

    /// 문자열 조회
    func getString(forKey key: String) throws -> String {
        let data = try getData(forKey: key)
        guard let string = String(data: data, encoding: .utf8) else {
            throw KeychainError.decodingError
        }
        return string
    }

    /// 데이터 조회
    func getData(forKey key: String) throws -> Data {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: key,
            kSecReturnData as String: true,
            kSecMatchLimit as String: kSecMatchLimitOne
        ]

        var result: AnyObject?
        let status = SecItemCopyMatching(query as CFDictionary, &result)

        guard status == errSecSuccess else {
            throw status == errSecItemNotFound ? KeychainError.itemNotFound : KeychainError.unhandledError(status: status)
        }

        guard let data = result as? Data else {
            throw KeychainError.unexpectedData
        }

        return data
    }

    /// 항목 삭제
    func delete(forKey key: String) throws {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: key
        ]

        let status = SecItemDelete(query as CFDictionary)
        guard status == errSecSuccess || status == errSecItemNotFound else {
            throw KeychainError.unhandledError(status: status)
        }
    }

    /// 모든 항목 삭제
    func deleteAll() throws {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service
        ]

        let status = SecItemDelete(query as CFDictionary)
        guard status == errSecSuccess || status == errSecItemNotFound else {
            throw KeychainError.unhandledError(status: status)
        }
    }
}
```

