import Foundation

/// 토큰 저장 및 관리 프로토콜
public protocol TokenManager {
    /// Access Token 저장
    func saveAccessToken(_ token: String) async throws

    /// Refresh Token 저장
    func saveRefreshToken(_ token: String) async throws

    /// Access Token 조회
    func getAccessToken() async throws -> String?

    /// Refresh Token 조회
    func getRefreshToken() async throws -> String?

    /// 토큰 쌍 저장
    func saveTokens(accessToken: String, refreshToken: String, expiresAt: Date) async throws

    /// Access Token 만료 여부 확인
    func isAccessTokenExpired() async -> Bool

    /// 토큰 만료 시각 조회
    func getTokenExpiryDate() async -> Date?

    /// 모든 토큰 삭제 (로그아웃)
    func clearTokens() async throws
}

/// 토큰 만료 정보
struct TokenExpiry: Codable {
    let expiresAt: Date
    let savedAt: Date
}
