### 3. TokenManagerImpl 구현

**DLNetworking/Sources/Auth/TokenManagerImpl.swift**
```swift
import Foundation
import DLCore

/// Keychain 기반 TokenManager 구현
public final class TokenManagerImpl: TokenManager {

    private let keychain: KeychainService
    private let logger: Logger

    // Keychain Keys
    private enum Keys {
        static let accessToken = "donelist.auth.accessToken"
        static let refreshToken = "donelist.auth.refreshToken"
        static let tokenExpiry = "donelist.auth.tokenExpiry"
    }

    // 메모리 캐시 (성능 최적화)
    private actor TokenCache {
        private var accessToken: String?
        private var refreshToken: String?
        private var expiry: TokenExpiry?

        func setAccessToken(_ token: String?) {
            self.accessToken = token
        }

        func setRefreshToken(_ token: String?) {
            self.refreshToken = token
        }

        func setExpiry(_ expiry: TokenExpiry?) {
            self.expiry = expiry
        }

        func getAccessToken() -> String? { accessToken }
        func getRefreshToken() -> String? { refreshToken }
        func getExpiry() -> TokenExpiry? { expiry }

        func clear() {
            accessToken = nil
            refreshToken = nil
            expiry = nil
        }
    }

    private let cache = TokenCache()

    public init(keychain: KeychainService = KeychainService(), logger: Logger = .shared) {
        self.keychain = keychain
        self.logger = logger
    }

    // MARK: - Public Methods

    public func saveAccessToken(_ token: String) async throws {
        try keychain.save(token, forKey: Keys.accessToken)
        await cache.setAccessToken(token)
        logger.info("Access token saved to Keychain")
    }

    public func saveRefreshToken(_ token: String) async throws {
        try keychain.save(token, forKey: Keys.refreshToken)
        await cache.setRefreshToken(token)
        logger.info("Refresh token saved to Keychain")
    }

    public func getAccessToken() async throws -> String? {
        // 캐시 우선 조회
        if let cached = await cache.getAccessToken() {
            return cached
        }

        // Keychain 조회
        do {
            let token = try keychain.getString(forKey: Keys.accessToken)
            await cache.setAccessToken(token)
            return token
        } catch KeychainService.KeychainError.itemNotFound {
            return nil
        }
    }

    public func getRefreshToken() async throws -> String? {
        if let cached = await cache.getRefreshToken() {
            return cached
        }

        do {
            let token = try keychain.getString(forKey: Keys.refreshToken)
            await cache.setRefreshToken(token)
            return token
        } catch KeychainService.KeychainError.itemNotFound {
            return nil
        }
    }

    public func saveTokens(accessToken: String, refreshToken: String, expiresAt: Date) async throws {
        // 토큰 저장
        try await saveAccessToken(accessToken)
        try await saveRefreshToken(refreshToken)

        // 만료 정보 저장
        let expiry = TokenExpiry(expiresAt: expiresAt, savedAt: Date())
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        let data = try encoder.encode(expiry)
        try keychain.save(data, forKey: Keys.tokenExpiry)
        await cache.setExpiry(expiry)

        logger.info("Token pair saved successfully", metadata: ["expiresAt": expiresAt.ISO8601String])
    }

    public func isAccessTokenExpired() async -> Bool {
        guard let expiry = await getTokenExpiry() else {
            return true // 만료 정보 없으면 만료로 간주
        }

        // 5분 버퍼 추가 (만료 5분 전부터 갱신 시도)
        let buffer: TimeInterval = 5 * 60
        return Date().addingTimeInterval(buffer) >= expiry.expiresAt
    }

    public func getTokenExpiryDate() async -> Date? {
        await getTokenExpiry()?.expiresAt
    }

    public func clearTokens() async throws {
        try keychain.delete(forKey: Keys.accessToken)
        try keychain.delete(forKey: Keys.refreshToken)
        try keychain.delete(forKey: Keys.tokenExpiry)
        await cache.clear()
        logger.info("All tokens cleared from Keychain")
    }

    // MARK: - Private Methods

    private func getTokenExpiry() async -> TokenExpiry? {
        if let cached = await cache.getExpiry() {
            return cached
        }

        do {
            let data = try keychain.getData(forKey: Keys.tokenExpiry)
            let decoder = JSONDecoder()
            decoder.dateDecodingStrategy = .iso8601
            let expiry = try decoder.decode(TokenExpiry.self, from: data)
            await cache.setExpiry(expiry)
            return expiry
        } catch {
            return nil
        }
    }
}
```

### 4. AuthInterceptor에 자동 토큰 갱신 로직 추가

**DLNetworking/Sources/Interceptors/AuthInterceptor.swift**
```swift
import Foundation
import DLCore

/// Bearer 토큰 자동 추가 및 401 시 토큰 갱신 인터셉터
public final class AuthInterceptor: RequestInterceptor {

    private let tokenManager: TokenManager
    private let refreshTokenAPI: RefreshTokenAPI
    private let logger: Logger

    // 갱신 중복 방지를 위한 actor
    private actor RefreshCoordinator {
        private var isRefreshing = false
        private var refreshTask: Task<String, Error>?

        func startRefresh(task: @escaping () async throws -> String) async throws -> String {
            // 이미 갱신 중이면 해당 Task 결과 재사용
            if let existingTask = refreshTask {
                return try await existingTask.value
            }

            isRefreshing = true
            let newTask = Task { try await task() }
            refreshTask = newTask

            defer {
                isRefreshing = false
                refreshTask = nil
            }

            return try await newTask.value
        }
    }

    private let coordinator = RefreshCoordinator()

    public init(tokenManager: TokenManager, refreshTokenAPI: RefreshTokenAPI, logger: Logger = .shared) {
        self.tokenManager = tokenManager
        self.refreshTokenAPI = refreshTokenAPI
        self.logger = logger
    }

    // MARK: - RequestInterceptor

    public func intercept(_ request: URLRequest) async throws -> URLRequest {
        var mutableRequest = request

        // Access Token 조회 및 추가
        if let accessToken = try await tokenManager.getAccessToken() {
            mutableRequest.setValue("Bearer \\(accessToken)", forHTTPHeaderField: "Authorization")
        }

        return mutableRequest
    }

    public func retry(_ request: URLRequest, for response: HTTPURLResponse, data: Data?) async throws -> Bool {
        // 401 Unauthorized 응답 시 토큰 갱신 시도
        guard response.statusCode == 401 else {
            return false // 재시도 안 함
        }

        logger.info("Received 401, attempting token refresh")

        do {
            // 토큰 갱신 (중복 방지)
            let newAccessToken = try await coordinator.startRefresh {
                try await self.performTokenRefresh()
            }

            logger.info("Token refresh successful")
            return true // 재시도

        } catch {
            logger.error("Token refresh failed", error: error)
            // 갱신 실패 시 로그아웃 처리 (Notification 발송)
            NotificationCenter.default.post(name: .authenticationFailed, object: nil)
            return false
        }
    }

    // MARK: - Private Methods

    private func performTokenRefresh() async throws -> String {
        guard let refreshToken = try await tokenManager.getRefreshToken() else {
            throw AppError.authenticationRequired
        }

        // Refresh Token API 호출
        let response = try await refreshTokenAPI.refresh(refreshToken: refreshToken)

        // 새 토큰 저장
        try await tokenManager.saveTokens(
            accessToken: response.accessToken,
            refreshToken: response.refreshToken,
            expiresAt: response.expiresAt
        )

        return response.accessToken
    }
}

// MARK: - Notification Extension

extension Notification.Name {
    static let authenticationFailed = Notification.Name("DoneList.authenticationFailed")
}
```

### 5. RefreshTokenAPI 정의

**DLNetworking/Sources/API/Auth/RefreshTokenAPI.swift**
```swift
import Foundation

/// Refresh Token API
protocol RefreshTokenAPI {
    func refresh(refreshToken: String) async throws -> RefreshTokenResponse
}

struct RefreshTokenResponse: Codable {
    let accessToken: String
    let refreshToken: String
    let expiresAt: Date

    enum CodingKeys: String, CodingKey {
        case accessToken = "access_token"
        case refreshToken = "refresh_token"
        case expiresAt = "expires_at"
    }
}

final class RefreshTokenAPIImpl: RefreshTokenAPI {
    private let apiClient: APIClient

    init(apiClient: APIClient) {
        self.apiClient = apiClient
    }

    func refresh(refreshToken: String) async throws -> RefreshTokenResponse {
        let request = RefreshTokenRequest(refreshToken: refreshToken)
        return try await apiClient.request(.refreshToken, method: .post, body: request)
    }
}

struct RefreshTokenRequest: Codable {
    let refreshToken: String

    enum CodingKeys: String, CodingKey {
        case refreshToken = "refresh_token"
    }
}
```

### 6. Endpoint에 Refresh Token 엔드포인트 추가

