import XCTest
@testable import DLNetworking

final class AuthInterceptorTests: XCTestCase {
    var tokenManager: TokenManagerImpl!
    var mockRefreshAPI: MockRefreshTokenAPI!
    var sut: AuthInterceptor!

    override func setUp() async throws {
        tokenManager = TokenManagerImpl(keychain: KeychainService(service: "com.donelist.test"))
        mockRefreshAPI = MockRefreshTokenAPI()
        sut = AuthInterceptor(tokenManager: tokenManager, refreshTokenAPI: mockRefreshAPI)
    }

    override func tearDown() async throws {
        try await tokenManager.clearTokens()
    }

    func testIntercept_AddsAuthorizationHeader() async throws {
        // Given
        try await tokenManager.saveAccessToken("test_token")
        var request = URLRequest(url: URL(string: "https://api.donelist.com/checkins")!)

        // When
        let interceptedRequest = try await sut.intercept(request)

        // Then
        XCTAssertEqual(interceptedRequest.value(forHTTPHeaderField: "Authorization"), "Bearer test_token")
    }

    func testRetry_On401_PerformsTokenRefresh() async throws {
        // Given
        try await tokenManager.saveRefreshToken("old_refresh")
        mockRefreshAPI.mockResponse = RefreshTokenResponse(
            accessToken: "new_access",
            refreshToken: "new_refresh",
            expiresAt: Date().addingTimeInterval(900)
        )

        let request = URLRequest(url: URL(string: "https://api.donelist.com")!)
        let response = HTTPURLResponse(url: request.url!, statusCode: 401, httpVersion: nil, headerFields: nil)!

        // When
        let shouldRetry = try await sut.retry(request, for: response, data: nil)

        // Then
        XCTAssertTrue(shouldRetry)
        XCTAssertEqual(mockRefreshAPI.callCount, 1)

        let newAccessToken = try await tokenManager.getAccessToken()
        XCTAssertEqual(newAccessToken, "new_access")
    }

    func testRetry_On401_RefreshFails_PostsNotification() async throws {
        // Given
        mockRefreshAPI.shouldFail = true

        let expectation = XCTestExpectation(description: "Authentication failed notification")
        let observer = NotificationCenter.default.addObserver(
            forName: .authenticationFailed,
            object: nil,
            queue: .main
        ) { _ in
            expectation.fulfill()
        }

        let request = URLRequest(url: URL(string: "https://api.donelist.com")!)
        let response = HTTPURLResponse(url: request.url!, statusCode: 401, httpVersion: nil, headerFields: nil)!

        // When
        let shouldRetry = try await sut.retry(request, for: response, data: nil)

        // Then
        XCTAssertFalse(shouldRetry)
        await fulfillment(of: [expectation], timeout: 1.0)

        NotificationCenter.default.removeObserver(observer)
    }

    func testConcurrentRefresh_OnlyRefreshesOnce() async throws {
        // Given
        try await tokenManager.saveRefreshToken("refresh")
        mockRefreshAPI.mockResponse = RefreshTokenResponse(
            accessToken: "new_access",
            refreshToken: "new_refresh",
            expiresAt: Date().addingTimeInterval(900)
        )
        mockRefreshAPI.delay = 0.5 // 0.5초 지연

        let request = URLRequest(url: URL(string: "https://api.donelist.com")!)
        let response = HTTPURLResponse(url: request.url!, statusCode: 401, httpVersion: nil, headerFields: nil)!

        // When: 동시에 3번 재시도 요청
        async let retry1 = sut.retry(request, for: response, data: nil)
        async let retry2 = sut.retry(request, for: response, data: nil)
        async let retry3 = sut.retry(request, for: response, data: nil)

        let results = try await [retry1, retry2, retry3]

        // Then: 모두 성공하지만 API는 1번만 호출됨
        XCTAssertTrue(results.allSatisfy { $0 == true })
        XCTAssertEqual(mockRefreshAPI.callCount, 1)
    }
}

// MARK: - Mock

class MockRefreshTokenAPI: RefreshTokenAPI {
    var mockResponse: RefreshTokenResponse?
    var shouldFail = false
    var callCount = 0
    var delay: TimeInterval = 0

    func refresh(refreshToken: String) async throws -> RefreshTokenResponse {
        callCount += 1

        if delay > 0 {
            try await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
        }

        if shouldFail {
            throw AppError.networkError(NSError(domain: "", code: -1))
        }

        guard let response = mockResponse else {
            throw AppError.unknown
        }

        return response
    }
}
```

