```swift
import Foundation
import DLCore

/// 로그인 Use Case
public final class LoginUseCase: Sendable {
    private let authRepository: AuthRepositoryProtocol
    private let logger: Logger

    public init(authRepository: AuthRepositoryProtocol, logger: Logger = .shared) {
        self.authRepository = authRepository
        self.logger = logger
    }

    /// 로그인 실행
    public func execute(email: String, password: String) async throws -> AuthResult {
        // 입력 검증
        guard !email.isEmpty else {
            logger.error("Login failed: empty email")
            throw AppError.validationError("이메일을 입력해주세요")
        }

        guard email.isValidEmail else {
            logger.error("Login failed: invalid email format")
            throw AppError.validationError("올바른 이메일 형식이 아닙니다")
        }

        guard !password.isEmpty else {
            logger.error("Login failed: empty password")
            throw AppError.validationError("비밀번호를 입력해주세요")
        }

        do {
            let result = try await authRepository.login(
                email: email.lowercased().trimmingCharacters(in: .whitespaces),
                password: password
            )

            // 로컬에 사용자 정보 캐시
            try await authRepository.cacheUser(result.user)

            logger.info("Login successful", metadata: ["user_id": result.user.id.uuidString])
            return result
        } catch {
            logger.error("Login failed", error: error)
            throw mapAuthError(error)
        }
    }

    private func mapAuthError(_ error: Error) -> AppError {
        if let appError = error as? AppError {
            return appError
        }

        // 백엔드 API 에러 처리 (/auth/login API 응답 기반)
        let errorDescription = error.localizedDescription

        if errorDescription.contains("invalid credentials") || errorDescription.contains("401") {
            return .authenticationError("이메일 또는 비밀번호가 일치하지 않습니다")
        }

        if errorDescription.contains("account locked") {
            return .authenticationError("계정이 잠겼습니다. 잠시 후 다시 시도해주세요")
        }

        if errorDescription.contains("network") {
            return .networkError("네트워크 연결을 확인해주세요")
        }

        return .unknownError("로그인에 실패했습니다. 다시 시도해주세요")
    }
}
```

**DLDomain/Sources/UseCases/Auth/RegisterUseCase.swift**
```swift
import Foundation
import DLCore

/// 회원가입 Use Case
public final class RegisterUseCase: Sendable {
    private let authRepository: AuthRepositoryProtocol
    private let logger: Logger

    public init(authRepository: AuthRepositoryProtocol, logger: Logger = .shared) {
        self.authRepository = authRepository
        self.logger = logger
    }

    /// 회원가입 실행
    public func execute(email: String, password: String, displayName: String?) async throws -> AuthResult {
        // 입력 검증
        try validateInputs(email: email, password: password, displayName: displayName)

        do {
            let result = try await authRepository.register(
                email: email.lowercased().trimmingCharacters(in: .whitespaces),
                password: password,
                displayName: displayName?.trimmingCharacters(in: .whitespaces)
            )

            // 로컬에 사용자 정보 캐시
            try await authRepository.cacheUser(result.user)

            logger.info("Registration successful", metadata: ["user_id": result.user.id.uuidString])
            return result
        } catch {
            logger.error("Registration failed", error: error)
            throw mapAuthError(error)
        }
    }

    private func validateInputs(email: String, password: String, displayName: String?) throws {
        // 이메일 검증
        guard !email.isEmpty else {
            throw AppError.validationError("이메일을 입력해주세요")
        }

        guard email.isValidEmail else {
            throw AppError.validationError("올바른 이메일 형식이 아닙니다")
        }

        // 비밀번호 검증 (백엔드 정책: 8-72자)
        guard !password.isEmpty else {
            throw AppError.validationError("비밀번호를 입력해주세요")
        }

        guard password.count >= 8 else {
            throw AppError.validationError("비밀번호는 최소 8자 이상이어야 합니다")
        }

        guard password.count <= 72 else {
            throw AppError.validationError("비밀번호는 최대 72자까지 가능합니다")
        }

        // 비밀번호 강도 검증 (영문, 숫자, 특수문자 중 2가지 이상)
        let hasLetter = password.range(of: "[A-Za-z]", options: .regularExpression) != nil
        let hasNumber = password.range(of: "[0-9]", options: .regularExpression) != nil
        let hasSpecial = password.range(of: "[^A-Za-z0-9]", options: .regularExpression) != nil

        let strengthCount = [hasLetter, hasNumber, hasSpecial].filter { $0 }.count
        guard strengthCount >= 2 else {
            throw AppError.validationError("비밀번호는 영문, 숫자, 특수문자 중 2가지 이상을 포함해야 합니다")
        }

        // 디스플레이 네임 검증 (선택 사항, 최대 100자)
        if let name = displayName, !name.isEmpty {
            guard name.count <= 100 else {
                throw AppError.validationError("이름은 최대 100자까지 가능합니다")
            }
        }
    }

    private func mapAuthError(_ error: Error) -> AppError {
        if let appError = error as? AppError {
            return appError
        }

        // 백엔드 API 에러 처리 (/auth/register API 응답 기반)
        let errorDescription = error.localizedDescription

        if errorDescription.contains("already registered") || errorDescription.contains("409") {
            return .validationError("이미 등록된 이메일입니다")
        }

        if errorDescription.contains("invalid password") {
            return .validationError("비밀번호 형식이 올바르지 않습니다")
        }

        if errorDescription.contains("network") {
            return .networkError("네트워크 연결을 확인해주세요")
        }

        return .unknownError("회원가입에 실패했습니다. 다시 시도해주세요")
    }
}
