        do {
            // 서버에 로그아웃 요청
            try await authRepository.logout(refreshToken: refreshToken)

            // 로컬 캐시 삭제
            try await authRepository.clearCachedUser()

            logger.info("Logout successful")
        } catch {
            logger.error("Logout failed", error: error)
            // 로그아웃 실패해도 로컬 캐시는 삭제
            try? await authRepository.clearCachedUser()
            throw AppError.unknownError("로그아웃에 실패했습니다")
        }
    }
