import Foundation
import DLCore

/// 현재 사용자 조회 Use Case
public final class GetCurrentUserUseCase: Sendable {
    private let authRepository: AuthRepositoryProtocol
    private let logger: Logger

    public init(authRepository: AuthRepositoryProtocol, logger: Logger = .shared) {
        self.authRepository = authRepository
        self.logger = logger
    }

    /// 현재 사용자 조회 (캐시 우선, 실패 시 서버 요청)
    public func execute() async throws -> User {
        // 로컬 캐시 먼저 확인
        if let cachedUser = await authRepository.getCachedUser() {
            logger.debug("User loaded from cache")
            return cachedUser
        }

        // 캐시 없으면 서버에서 조회
        do {
            let user = try await authRepository.getCurrentUser()
            try await authRepository.cacheUser(user)
            logger.info("User loaded from server")
            return user
        } catch {
            logger.error("Failed to get current user", error: error)
            throw AppError.authenticationError("사용자 정보를 불러올 수 없습니다")
        }
    }
}
