**DLData/Sources/Mappers/AuthMapper.swift**
```swift
import Foundation
import DLDomain
import DLCore

/// 인증 관련 DTO ↔ Domain 매퍼
enum AuthMapper {
    /// AuthResponseDTO → AuthResult
    static func toDomain(_ dto: AuthResponseDTO) throws -> AuthResult {
        let user = try UserMapper.toDomain(dto.user)
        let tokenPair = try toTokenPair(
            accessToken: dto.accessToken,
            refreshToken: dto.refreshToken,
            expiresAt: dto.expiresAt
        )

        return AuthResult(user: user, tokenPair: tokenPair)
    }

    /// TokenRefreshResponseDTO → TokenPair
    static func toDomain(_ dto: TokenRefreshResponseDTO) throws -> TokenPair {
        return try toTokenPair(
            accessToken: dto.accessToken,
            refreshToken: dto.refreshToken,
            expiresAt: dto.expiresAt
        )
    }

    private static func toTokenPair(accessToken: String, refreshToken: String, expiresAt: String) throws -> TokenPair {
        guard let expiryDate = expiresAt.toISO8601Date() else {
            throw AppError.decodingError("Invalid expires_at format: \(expiresAt)")
        }

        return TokenPair(
            accessToken: accessToken,
            refreshToken: refreshToken,
            expiresAt: expiryDate
        )
    }
}

/// 사용자 DTO → Domain 매퍼
enum UserMapper {
    static func toDomain(_ dto: UserDTO) throws -> User {
        guard let userId = UUID(uuidString: dto.id) else {
            throw AppError.decodingError("Invalid user ID format: \(dto.id)")
        }

        guard let role = UserRole(rawValue: dto.role) else {
            throw AppError.decodingError("Invalid user role: \(dto.role)")
        }

        guard let tier = SubscriptionTier(rawValue: dto.subscriptionTier) else {
            throw AppError.decodingError("Invalid subscription tier: \(dto.subscriptionTier)")
        }

        guard let mode = AppMode(rawValue: dto.appMode) else {
            throw AppError.decodingError("Invalid app mode: \(dto.appMode)")
        }

        guard let createdAt = dto.createdAt.toISO8601Date() else {
            throw AppError.decodingError("Invalid created_at format: \(dto.createdAt)")
        }

        guard let updatedAt = dto.updatedAt.toISO8601Date() else {
            throw AppError.decodingError("Invalid updated_at format: \(dto.updatedAt)")
        }

        return User(
            id: userId,
            email: dto.email,
            displayName: dto.displayName,
            avatarURL: dto.avatarURL,
            role: role,
            subscriptionTier: tier,
            appMode: mode,
            createdAt: createdAt,
            updatedAt: updatedAt
        )
    }
}
