import Foundation
import DLNetworking
import DLCore

/// 인증 원격 데이터 소스
final class AuthRemoteDataSource: Sendable {
    private let apiClient: APIClient
    private let logger: Logger

    init(apiClient: APIClient, logger: Logger = .shared) {
        self.apiClient = apiClient
        self.logger = logger
    }

    /// 회원가입 API 호출 (POST /auth/register)
    func register(email: String, password: String, displayName: String?) async throws -> AuthResponseDTO {
        let request = RegisterRequestDTO(
            email: email,
            password: password,
            displayName: displayName
        )

        return try await apiClient.request(
            endpoint: .register,
            method: .post,
            body: request,
            responseType: AuthResponseDTO.self
        )
    }

    /// 로그인 API 호출 (POST /auth/login)
    func login(email: String, password: String) async throws -> AuthResponseDTO {
        let request = LoginRequestDTO(email: email, password: password)

        return try await apiClient.request(
            endpoint: .login,
            method: .post,
            body: request,
            responseType: AuthResponseDTO.self
        )
    }

    /// 토큰 갱신 API 호출 (POST /auth/refresh)
    func refreshToken(_ refreshToken: String) async throws -> TokenRefreshResponseDTO {
        let request = RefreshRequestDTO(refreshToken: refreshToken)

        return try await apiClient.request(
            endpoint: .refreshToken,
            method: .post,
            body: request,
            responseType: TokenRefreshResponseDTO.self
        )
    }

    /// 로그아웃 API 호출 (POST /auth/logout)
    func logout(refreshToken: String) async throws {
        let request = LogoutRequestDTO(refreshToken: refreshToken)

        try await apiClient.request(
            endpoint: .logout,
            method: .post,
            body: request,
            responseType: EmptyResponse.self
        )
    }

    /// 현재 사용자 조회 API 호출 (GET /users/me)
    func getCurrentUser() async throws -> UserDTO {
        return try await apiClient.request(
            endpoint: .currentUser,
            method: .get,
            responseType: UserDTO.self
        )
    }
}
