**DLData/Sources/DataSources/AuthLocalDataSource.swift**
```swift
import Foundation
import SwiftData
import DLDomain
import DLCore

/// 인증 로컬 데이터 소스 (SwiftData)
@ModelActor
actor AuthLocalDataSource {
    private let logger: Logger

    init(modelContainer: ModelContainer, logger: Logger = .shared) {
        self.modelContainer = modelContainer
        self.logger = logger
    }

    /// 사용자 캐시 저장
    func cacheUser(_ user: User) throws {
        // 기존 캐시 삭제
        try clearCachedUser()

        // 새 캐시 저장
        let entity = UserEntity(from: user)
        modelContext.insert(entity)
        try modelContext.save()

        logger.debug("User cached successfully", metadata: ["user_id": user.id.uuidString])
    }

    /// 캐시된 사용자 조회
    func getCachedUser() throws -> User? {
        let descriptor = FetchDescriptor<UserEntity>()
        let entities = try modelContext.fetch(descriptor)

        guard let entity = entities.first else {
            logger.debug("No cached user found")
            return nil
        }

        logger.debug("Cached user loaded", metadata: ["user_id": entity.id.uuidString])
        return entity.toDomain()
    }

    /// 사용자 캐시 삭제
    func clearCachedUser() throws {
        let descriptor = FetchDescriptor<UserEntity>()
        let entities = try modelContext.fetch(descriptor)

        for entity in entities {
            modelContext.delete(entity)
        }

        try modelContext.save()
        logger.debug("User cache cleared")
    }
}

/// SwiftData 사용자 엔티티
@Model
final class UserEntity {
    @Attribute(.unique) var id: UUID
    var email: String
    var displayName: String?
    var avatarURL: String?
    var roleRawValue: String
    var subscriptionTierRawValue: String
    var appModeRawValue: String
    var createdAt: Date
    var updatedAt: Date

    init(from user: User) {
        self.id = user.id
        self.email = user.email
        self.displayName = user.displayName
        self.avatarURL = user.avatarURL
        self.roleRawValue = user.role.rawValue
        self.subscriptionTierRawValue = user.subscriptionTier.rawValue
        self.appModeRawValue = user.appMode.rawValue
        self.createdAt = user.createdAt
        self.updatedAt = user.updatedAt
    }

    func toDomain() -> User {
        User(
            id: id,
            email: email,
            displayName: displayName,
            avatarURL: avatarURL,
            role: UserRole(rawValue: roleRawValue) ?? .user,
            subscriptionTier: SubscriptionTier(rawValue: subscriptionTierRawValue) ?? .free,
            appMode: AppMode(rawValue: appModeRawValue) ?? .personal,
            createdAt: createdAt,
            updatedAt: updatedAt
        )
    }
}
