import Foundation
import DLDomain
import DLCore

/// 인증 저장소 구현체
public final class AuthRepositoryImpl: AuthRepositoryProtocol {
    private let remoteDataSource: AuthRemoteDataSource
    private let localDataSource: AuthLocalDataSource
    private let logger: Logger

    public init(
        remoteDataSource: AuthRemoteDataSource,
        localDataSource: AuthLocalDataSource,
        logger: Logger = .shared
    ) {
        self.remoteDataSource = remoteDataSource
        self.localDataSource = localDataSource
        self.logger = logger
    }

    public func register(email: String, password: String, displayName: String?) async throws -> AuthResult {
        let dto = try await remoteDataSource.register(
            email: email,
            password: password,
            displayName: displayName
        )
        return try AuthMapper.toDomain(dto)
    }

    public func login(email: String, password: String) async throws -> AuthResult {
        let dto = try await remoteDataSource.login(email: email, password: password)
        return try AuthMapper.toDomain(dto)
    }

    public func refreshToken(_ refreshToken: String) async throws -> TokenPair {
        let dto = try await remoteDataSource.refreshToken(refreshToken)
        return try AuthMapper.toDomain(dto)
    }

    public func logout(refreshToken: String) async throws {
        try await remoteDataSource.logout(refreshToken: refreshToken)
    }

    public func getCurrentUser() async throws -> User {
        let dto = try await remoteDataSource.getCurrentUser()
        return try UserMapper.toDomain(dto)
    }

    public func getCachedUser() async -> User? {
        return try? await localDataSource.getCachedUser()
    }

    public func cacheUser(_ user: User) async throws {
        try await localDataSource.cacheUser(user)
    }

    public func clearCachedUser() async throws {
        try await localDataSource.clearCachedUser()
    }
}
