### 6. AuthViewModel 구현

**DLPresentation/Sources/ViewModels/AuthViewModel.swift**
```swift
import Foundation
import Observation
import DLDomain
import DLCore

/// 인증 화면 ViewModel
@Observable
public final class AuthViewModel {
    // Dependencies
    private let loginUseCase: LoginUseCase
    private let registerUseCase: RegisterUseCase

    // Form State
    public var email: String = ""
    public var password: String = ""
    public var passwordConfirmation: String = ""
    public var displayName: String = ""

    // UI State
    public var isLoading: Bool = false
    public var showError: Bool = false
    public var errorMessage: String = ""
    public var showRegisterView: Bool = false

    // Authentication State
    public var isAuthenticated: Bool = false
    public var currentUser: User?

    // Computed Properties
    public var isLoginButtonEnabled: Bool {
        !email.isEmpty && !password.isEmpty
    }

    public var isRegisterButtonEnabled: Bool {
        !email.isEmpty &&
        !password.isEmpty &&
        !passwordConfirmation.isEmpty &&
        passwordsMatch &&
        password.count >= 8 &&
        password.count <= 72 &&
        passwordStrengthMet
    }

    public var passwordsMatch: Bool {
        password == passwordConfirmation
    }

    public var passwordStrengthMet: Bool {
        let hasLetter = password.range(of: "[A-Za-z]", options: .regularExpression) != nil
        let hasNumber = password.range(of: "[0-9]", options: .regularExpression) != nil
        let hasSpecial = password.range(of: "[^A-Za-z0-9]", options: .regularExpression) != nil

        let strengthCount = [hasLetter, hasNumber, hasSpecial].filter { $0 }.count
        return strengthCount >= 2
    }

    public init(loginUseCase: LoginUseCase, registerUseCase: RegisterUseCase) {
        self.loginUseCase = loginUseCase
        self.registerUseCase = registerUseCase
    }

    // MARK: - Actions

    /// 로그인 실행
    @MainActor
    public func login() async {
        guard !isLoading else { return }

        isLoading = true
        defer { isLoading = false }

        do {
            let result = try await loginUseCase.execute(email: email, password: password)

            // 토큰 저장 (TokenManager 사용 - Task 23에서 구현)
            await storeTokens(result.tokenPair)

            // 인증 성공
            currentUser = result.user
            isAuthenticated = true

            // 폼 초기화
            resetForm()
        } catch {
            handleError(error)
        }
    }

    /// 회원가입 실행
    @MainActor
    public func register() async {
        guard !isLoading else { return }

        isLoading = true
        defer { isLoading = false }

        do {
            let name = displayName.isEmpty ? nil : displayName
            let result = try await registerUseCase.execute(
                email: email,
                password: password,
                displayName: name
            )

            // 토큰 저장 (TokenManager 사용 - Task 23에서 구현)
            await storeTokens(result.tokenPair)

            // 인증 성공
            currentUser = result.user
            isAuthenticated = true

            // 폼 초기화
            resetForm()
        } catch {
            handleError(error)
        }
    }

    // MARK: - Private Methods

    private func resetForm() {
        email = ""
        password = ""
        passwordConfirmation = ""
        displayName = ""
    }

    @MainActor
    private func handleError(_ error: Error) {
        if let appError = error as? AppError {
            errorMessage = appError.localizedDescription
        } else {
            errorMessage = "알 수 없는 오류가 발생했습니다"
        }
        showError = true
    }

    private func storeTokens(_ tokenPair: TokenPair) async {
        // TODO: Task 23에서 구현될 TokenManager 사용
        // await tokenManager.save(accessToken: tokenPair.accessToken)
        // await tokenManager.save(refreshToken: tokenPair.refreshToken)
        print("Tokens stored: \(tokenPair.accessToken)")
    }
}
