import Foundation
import DLDomain
import DLNetworking

/// 카테고리 Repository Protocol
public protocol CategoryRepositoryProtocol: Sendable {
    func getCategories() async throws -> [Category]
    func getCategory(id: UUID) async throws -> Category
    func createCategory(_ input: CreateCategoryInput) async throws -> Category
    func updateCategory(id: UUID, _ input: UpdateCategoryInput) async throws -> Category
    func deleteCategory(id: UUID) async throws
    func getRecommendedColors(count: Int) async throws -> [String]
}

/// 카테고리 Repository 구현
public final class CategoryRepository: CategoryRepositoryProtocol, @unchecked Sendable {
    private let apiClient: APIClient

    public init(apiClient: APIClient) {
        self.apiClient = apiClient
    }

    public func getCategories() async throws -> [Category] {
        let response: CategoriesResponse = try await apiClient.request(
            endpoint: "/api/v1/categories",
            method: .get
        )
        return response.categories
    }

    public func getCategory(id: UUID) async throws -> Category {
        try await apiClient.request(
            endpoint: "/api/v1/categories/\(id.uuidString)",
            method: .get
        )
    }

    public func createCategory(_ input: CreateCategoryInput) async throws -> Category {
        try await apiClient.request(
            endpoint: "/api/v1/categories",
            method: .post,
            body: input
        )
    }

    public func updateCategory(id: UUID, _ input: UpdateCategoryInput) async throws -> Category {
        try await apiClient.request(
            endpoint: "/api/v1/categories/\(id.uuidString)",
            method: .patch,
            body: input
        )
    }

    public func deleteCategory(id: UUID) async throws {
        let _: EmptyResponse = try await apiClient.request(
            endpoint: "/api/v1/categories/\(id.uuidString)",
            method: .delete
        )
    }

    public func getRecommendedColors(count: Int = 5) async throws -> [String] {
        let response: RecommendedColorsResponse = try await apiClient.request(
            endpoint: "/api/v1/categories/colors/recommendations",
            method: .get,
            queryParameters: ["count": "\(count)"]
        )
        return response.recommendations
    }
}

// Response DTOs
private struct CategoriesResponse: Codable {
    let categories: [Category]
}

private struct RecommendedColorsResponse: Codable {
    let recommendations: [String]
}

private struct EmptyResponse: Codable {}
