### 3. Use Case 레이어 구현

**DLDomain/Sources/UseCases/Category/ManageCategoriesUseCase.swift**
```swift
import Foundation

/// 카테고리 관리 UseCase
public protocol ManageCategoriesUseCaseProtocol: Sendable {
    func execute() async throws -> [Category]
    func create(_ input: CreateCategoryInput) async throws -> Category
    func update(id: UUID, _ input: UpdateCategoryInput) async throws -> Category
    func delete(id: UUID) async throws
    func getRecommendedColors(count: Int) async throws -> [String]
}

public final class ManageCategoriesUseCase: ManageCategoriesUseCaseProtocol, @unchecked Sendable {
    private let categoryRepository: CategoryRepositoryProtocol

    public init(categoryRepository: CategoryRepositoryProtocol) {
        self.categoryRepository = categoryRepository
    }

    public func execute() async throws -> [Category] {
        try await categoryRepository.getCategories()
    }

    public func create(_ input: CreateCategoryInput) async throws -> Category {
        // 비즈니스 로직: 이름 검증
        guard !input.name.trimmingCharacters(in: .whitespaces).isEmpty else {
            throw CategoryError.emptyName
        }

        guard input.name.count <= 50 else {
            throw CategoryError.nameTooLong
        }

        return try await categoryRepository.createCategory(input)
    }

    public func update(id: UUID, _ input: UpdateCategoryInput) async throws -> Category {
        // 비즈니스 로직: 이름 검증 (제공된 경우)
        if let name = input.name {
            guard !name.trimmingCharacters(in: .whitespaces).isEmpty else {
                throw CategoryError.emptyName
            }

            guard name.count <= 50 else {
                throw CategoryError.nameTooLong
            }
        }

        return try await categoryRepository.updateCategory(id: id, input)
    }

    public func delete(id: UUID) async throws {
        try await categoryRepository.deleteCategory(id: id)
    }

    public func getRecommendedColors(count: Int = 5) async throws -> [String] {
        try await categoryRepository.getRecommendedColors(count: count)
    }
}

// Category 관련 에러
public enum CategoryError: LocalizedError {
    case emptyName
    case nameTooLong
    case colorSimilarToExisting(String)
    case notFound

    public var errorDescription: String? {
        switch self {
        case .emptyName: return "카테고리 이름은 비어있을 수 없습니다"
        case .nameTooLong: return "카테고리 이름은 50자를 초과할 수 없습니다"
        case .colorSimilarToExisting(let name): return "'\(name)' 카테고리와 색상이 너무 유사합니다"
        case .notFound: return "카테고리를 찾을 수 없습니다"
        }
    }
}
```

