            .sheet(isPresented: $showIconPicker) {
                IconPickerView(selectedIcon: $selectedIcon)
            }
            .onAppear {
                if case .edit(let category) = mode {
                    name = category.name
                    selectedColor = category.color
                    selectedIcon = category.icon
                }
            }
        }
    }
}

