import Foundation
import Combine
import DLDomain
import DLCore

@MainActor
final class CategoryManagementViewModel: ObservableObject {
    @Published var categories: [Category] = []
    @Published var showAddSheet = false
    @Published var showEditSheet = false
    @Published var selectedCategory: Category?
    @Published var showError = false
    @Published var errorMessage: String?

    private let manageCategoriesUseCase: ManageCategoriesUseCaseProtocol
    private let logger: Logger
    private var cancellables = Set<AnyCancellable>()

    init(
        manageCategoriesUseCase: ManageCategoriesUseCaseProtocol,
        logger: Logger
    ) {
        self.manageCategoriesUseCase = manageCategoriesUseCase
        self.logger = logger
    }

    func loadCategories() async {
        do {
            categories = try await manageCategoriesUseCase.execute()
            logger.info("카테고리 로드 완료: \(categories.count)개")
        } catch {
            logger.error("카테고리 로드 실패", error: error)
            showErrorAlert(message: "카테고리를 불러올 수 없습니다")
        }
    }

    func createCategory(name: String, color: String?, icon: String?) async {
        do {
            let input = CreateCategoryInput(name: name, color: color, icon: icon)
            let newCategory = try await manageCategoriesUseCase.create(input)
            categories.append(newCategory)
            logger.info("카테고리 생성 완료: \(newCategory.name)")
        } catch {
            logger.error("카테고리 생성 실패", error: error)
            showErrorAlert(message: error.localizedDescription)
        }
    }

    func updateCategory(id: UUID, name: String, color: String?, icon: String?) async {
        do {
            let input = UpdateCategoryInput(name: name, color: color, icon: icon)
            let updated = try await manageCategoriesUseCase.update(id: id, input)

            if let index = categories.firstIndex(where: { $0.id == id }) {
                categories[index] = updated
            }
            logger.info("카테고리 업데이트 완료: \(updated.name)")
        } catch {
            logger.error("카테고리 업데이트 실패", error: error)
            showErrorAlert(message: error.localizedDescription)
        }
    }

    func deleteCategory(_ category: Category) {
        Task {
            do {
                try await manageCategoriesUseCase.delete(id: category.id)
                categories.removeAll { $0.id == category.id }
                logger.info("카테고리 삭제 완료: \(category.name)")
            } catch {
                logger.error("카테고리 삭제 실패", error: error)
                showErrorAlert(message: "카테고리를 삭제할 수 없습니다")
            }
        }
    }

    private func showErrorAlert(message: String) {
        errorMessage = message
        showError = true
    }
}
