import Foundation
import Combine
import DLDomain
import DLCore

@MainActor
final class TagAutocompleteViewModel: ObservableObject {
    @Published var searchQuery: String = ""
    @Published var suggestions: [Tag] = []
    @Published var popularTags: [Tag] = []

    private let manageTagsUseCase: ManageTagsUseCaseProtocol
    private let logger: Logger
    private var cancellables = Set<AnyCancellable>()

    init(
        manageTagsUseCase: ManageTagsUseCaseProtocol,
        logger: Logger
    ) {
        self.manageTagsUseCase = manageTagsUseCase
        self.logger = logger

        setupSearchDebounce()
    }

    private func setupSearchDebounce() {
        $searchQuery
            .debounce(for: .milliseconds(300), scheduler: DispatchQueue.main)
            .removeDuplicates()
            .sink { [weak self] query in
                Task {
                    await self?.searchTags(query: query)
                }
            }
            .store(in: &cancellables)
    }

    func loadPopularTags() async {
        do {
            popularTags = try await manageTagsUseCase.getPopularTags()
            logger.info("인기 태그 로드 완료: \(popularTags.count)개")
        } catch {
            logger.error("인기 태그 로드 실패", error: error)
        }
    }

    private func searchTags(query: String) async {
        guard !query.isEmpty else {
            suggestions = []
            return
        }

        do {
            suggestions = try await manageTagsUseCase.autocomplete(query: query)
            logger.debug("태그 검색 완료: \(suggestions.count)개 (query: \(query))")
        } catch {
            logger.error("태그 검색 실패", error: error)
            suggestions = []
        }
    }
}
