import Foundation
import DLCore

/// 월별 캘린더 조회 Use Case
public final class GetMonthlyCalendarUseCase {
    private let repository: CalendarRepository
    private let logger: Logger

    public init(repository: CalendarRepository, logger: Logger = .shared) {
        self.repository = repository
        self.logger = logger
    }

    /// 월별 캘린더 데이터 조회
    /// - Parameters:
    ///   - year: 년도 (기본: 현재 년도)
    ///   - month: 월 (기본: 현재 월)
    ///   - startDay: 주 시작 요일 (기본: monday)
    ///   - timezone: 타임존 (기본: 시스템 타임존)
    /// - Returns: MonthlyCalendar
    public func execute(
        year: Int? = nil,
        month: Int? = nil,
        startDay: StartDay = .monday,
        timezone: String? = nil
    ) async throws -> MonthlyCalendar {
        let now = Date()
        let calendar = Calendar.current

        let targetYear = year ?? calendar.component(.year, from: now)
        let targetMonth = month ?? calendar.component(.month, from: now)
        let tz = timezone ?? TimeZone.current.identifier

        // Validate month range
        guard (1...12).contains(targetMonth) else {
            logger.error("Invalid month: \(targetMonth)")
            throw AppError.validationFailed("월은 1-12 사이여야 합니다")
        }

        logger.info("Fetching monthly calendar: \(targetYear)-\(targetMonth)")

        do {
            let result = try await repository.getMonthlyCalendar(
                year: targetYear,
                month: targetMonth,
                startDay: startDay,
                timezone: tz
            )

            logger.info("Successfully fetched monthly calendar")
            return result
        } catch {
            logger.error("Failed to fetch monthly calendar: \(error)")
            throw error
        }
    }
}
```

