import Foundation
import DLCore

/// 히트맵 데이터 조회 Use Case
public final class GetHeatmapDataUseCase {
    private let repository: CalendarRepository
    private let logger: Logger

    public init(repository: CalendarRepository, logger: Logger = .shared) {
        self.repository = repository
        self.logger = logger
    }

    /// 최근 N일 히트맵 데이터 조회
    /// - Parameters:
    ///   - days: 조회할 일수 (기본: 365일)
    ///   - timezone: 타임존 (기본: 시스템 타임존)
    /// - Returns: HeatmapData
    public func execute(
        days: Int = 365,
        timezone: String? = nil
    ) async throws -> HeatmapData {
        let now = Date()
        let calendar = Calendar.current
        let tz = timezone ?? TimeZone.current.identifier

        // Calculate start date (N days ago)
        guard let startDate = calendar.date(byAdding: .day, value: -days, to: now) else {
            throw AppError.unknown("날짜 계산 실패")
        }

        let dateFormatter = ISO8601DateFormatter()
        dateFormatter.formatOptions = [.withFullDate]

        let startDateStr = dateFormatter.string(from: startDate)
        let endDateStr = dateFormatter.string(from: now)

        logger.info("Fetching heatmap data: \(startDateStr) to \(endDateStr)")

        do {
            let result = try await repository.getHeatmapData(
                startDate: startDateStr,
                endDate: endDateStr,
                timezone: tz
            )

            logger.info("Successfully fetched heatmap data: \(result.activeDays)/\(result.totalDays) active days")
            return result
        } catch {
            logger.error("Failed to fetch heatmap data: \(error)")
            throw error
        }
    }

    /// 특정 날짜 범위 히트맵 데이터 조회
    /// - Parameters:
    ///   - startDate: 시작 날짜 (YYYY-MM-DD)
    ///   - endDate: 종료 날짜 (YYYY-MM-DD)
    ///   - timezone: 타임존
    /// - Returns: HeatmapData
    public func execute(
        startDate: String,
        endDate: String,
        timezone: String? = nil
    ) async throws -> HeatmapData {
        let tz = timezone ?? TimeZone.current.identifier

        logger.info("Fetching heatmap data: \(startDate) to \(endDate)")

        do {
            let result = try await repository.getHeatmapData(
                startDate: startDate,
                endDate: endDate,
                timezone: tz
            )

            logger.info("Successfully fetched heatmap data")
            return result
        } catch {
            logger.error("Failed to fetch heatmap data: \(error)")
            throw error
        }
    }
}
