import Foundation
import DLDomain
import DLCore

/// Calendar DTO → Domain 매퍼
struct CalendarMapper {
    static func toDomain(_ dto: MonthlyCalendarDTO) throws -> MonthlyCalendar {
        let iso8601 = ISO8601DateFormatter()

        guard let generatedAt = iso8601.date(from: dto.generatedAt) else {
            throw AppError.decodingFailed("Invalid generatedAt date")
        }

        guard let cacheExpiration = iso8601.date(from: dto.cacheExpiration) else {
            throw AppError.decodingFailed("Invalid cacheExpiration date")
        }

        let startDay = StartDay(rawValue: dto.startDay) ?? .monday

        return MonthlyCalendar(
            year: dto.year,
            month: dto.month,
            monthName: dto.monthName,
            startDay: startDay,
            weeks: dto.weeks.map(toDomain),
            summary: toDomain(dto.summary),
            categories: dto.categories.map(toDomain),
            previousMonth: dto.previousMonth,
            nextMonth: dto.nextMonth,
            generatedAt: generatedAt,
            cacheExpiration: cacheExpiration
        )
    }

    static func toDomain(_ dto: CalendarWeekDTO) -> CalendarWeek {
        CalendarWeek(days: dto.days.map(toDomain))
    }

    static func toDomain(_ dto: CalendarDayDTO) -> CalendarDay {
        CalendarDay(
            date: dto.date,
            checkinCount: dto.checkinCount,
            totalMinutes: dto.totalMinutes,
            completionPercent: dto.completionPercent,
            colorIntensity: dto.colorIntensity,
            isCurrentMonth: dto.isCurrentMonth,
            isToday: dto.isToday,
            hasCheckins: dto.hasCheckins
        )
    }

    static func toDomain(_ dto: MonthlySummaryDTO) -> MonthlySummary {
        MonthlySummary(
            totalCheckins: dto.totalCheckins,
            totalMinutes: dto.totalMinutes,
            daysWithCheckins: dto.daysWithCheckins,
            totalDaysInMonth: dto.totalDaysInMonth,
            averagePerDay: dto.averagePerDay,
            completionRate: dto.completionRate,
            mostProductiveDay: dto.mostProductiveDay,
            mostProductiveCount: dto.mostProductiveCount,
            currentStreak: dto.currentStreak,
            longestStreak: dto.longestStreak
        )
    }

    static func toDomain(_ dto: CategoryBreakdownDTO) -> CategoryBreakdown {
        let id = dto.categoryId.flatMap { UUID(uuidString: $0) }
        return CategoryBreakdown(
            id: id,
            categoryName: dto.categoryName,
            count: dto.count,
            percentage: dto.percentage
        )
    }

    static func toDomain(_ dto: HeatmapDataDTO) throws -> HeatmapData {
        let iso8601 = ISO8601DateFormatter()

        guard let generatedAt = iso8601.date(from: dto.generatedAt) else {
            throw AppError.decodingFailed("Invalid generatedAt date")
        }

        return HeatmapData(
            startDate: dto.startDate,
            endDate: dto.endDate,
            days: dto.days.map(toDomain),
            totalDays: dto.totalDays,
            activeDays: dto.activeDays,
            totalCheckins: dto.totalCheckins,
            generatedAt: generatedAt
        )
    }

    static func toDomain(_ dto: HeatmapDayDTO) -> HeatmapDay {
        HeatmapDay(
            date: dto.date,
            checkinCount: dto.checkinCount,
            totalMinutes: dto.totalMinutes,
            completionPercent: dto.completionPercent,
            colorIntensity: dto.colorIntensity
        )
    }
}
