import Foundation
import DLDomain
import DLCore
import Observation

/// 캘린더 탭 ViewModel
@Observable
public final class CalendarViewModel {
    // Dependencies
    private let getMonthlyCalendarUseCase: GetMonthlyCalendarUseCase
    private let getHeatmapDataUseCase: GetHeatmapDataUseCase
    private let logger: Logger

    // State
    public var monthlyCalendar: MonthlyCalendar?
    public var heatmapData: HeatmapData?
    public var selectedDay: CalendarDay?
    public var isLoading = false
    public var errorMessage: String?

    // View mode
    public enum ViewMode {
        case monthly
        case heatmap
    }
    public var viewMode: ViewMode = .monthly

    // Current selection
    public var currentYear: Int
    public var currentMonth: Int
    public var startDay: StartDay = .monday

    public init(
        getMonthlyCalendarUseCase: GetMonthlyCalendarUseCase,
        getHeatmapDataUseCase: GetHeatmapDataUseCase,
        logger: Logger = .shared
    ) {
        self.getMonthlyCalendarUseCase = getMonthlyCalendarUseCase
        self.getHeatmapDataUseCase = getHeatmapDataUseCase
        self.logger = logger

        let now = Date()
        let calendar = Calendar.current
        self.currentYear = calendar.component(.year, from: now)
        self.currentMonth = calendar.component(.month, from: now)
    }

    /// 월별 캘린더 로드
    @MainActor
    public func loadMonthlyCalendar() async {
        isLoading = true
        errorMessage = nil

        do {
            let calendar = try await getMonthlyCalendarUseCase.execute(
                year: currentYear,
                month: currentMonth,
                startDay: startDay,
                timezone: TimeZone.current.identifier
            )

            self.monthlyCalendar = calendar
            logger.info("Monthly calendar loaded successfully")
        } catch {
            logger.error("Failed to load monthly calendar: \(error)")
            errorMessage = error.localizedDescription
        }

        isLoading = false
    }

    /// 히트맵 데이터 로드
    @MainActor
    public func loadHeatmapData(days: Int = 365) async {
        isLoading = true
        errorMessage = nil

        do {
            let heatmap = try await getHeatmapDataUseCase.execute(
                days: days,
                timezone: TimeZone.current.identifier
            )

            self.heatmapData = heatmap
            logger.info("Heatmap data loaded successfully")
        } catch {
            logger.error("Failed to load heatmap data: \(error)")
            errorMessage = error.localizedDescription
        }

        isLoading = false
    }

    /// 이전 달로 이동
    @MainActor
    public func navigateToPreviousMonth() async {
        if currentMonth == 1 {
            currentMonth = 12
            currentYear -= 1
        } else {
            currentMonth -= 1
        }

        await loadMonthlyCalendar()
    }

    /// 다음 달로 이동
    @MainActor
    public func navigateToNextMonth() async {
        if currentMonth == 12 {
            currentMonth = 1
            currentYear += 1
        } else {
            currentMonth += 1
        }

        await loadMonthlyCalendar()
    }

    /// 오늘로 이동
    @MainActor
    public func navigateToToday() async {
        let now = Date()
        let calendar = Calendar.current
        currentYear = calendar.component(.year, from: now)
        currentMonth = calendar.component(.month, from: now)

        await loadMonthlyCalendar()
    }

    /// 날짜 선택
    public func selectDay(_ day: CalendarDay) {
        selectedDay = day
    }

    /// 선택 해제
    public func deselectDay() {
        selectedDay = nil
    }

    /// View Mode 전환
    @MainActor
    public func switchViewMode(to mode: ViewMode) async {
        viewMode = mode

        switch mode {
        case .monthly:
            await loadMonthlyCalendar()
        case .heatmap:
            await loadHeatmapData()
        }
    }
}
