/// GitHub 스타일 히트맵 그리드
struct HeatmapGridView: View {
    let days: [HeatmapDay]
    let onDayTap: (HeatmapDay) -> Void

    private let columns = 53 // ~1 year worth of weeks
    private let cellSize: CGFloat = 12
    private let spacing: CGFloat = 3

    var body: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            VStack(alignment: .leading, spacing: spacing) {
                // Weekday labels
                ForEach(0..<7) { weekday in
                    HStack(spacing: spacing) {
                        Text(weekdayLabel(weekday))
                            .font(.system(size: 10))
                            .foregroundStyle(.secondary)
                            .frame(width: 30, alignment: .leading)

                        ForEach(chunkedDays[weekday], id: \.date) { day in
                            HeatmapCell(day: day)
                                .onTapGesture {
                                    onDayTap(day)
                                }
                        }
                    }
                }
            }
            .padding()
        }
    }

    private var chunkedDays: [[HeatmapDay]] {
        // Group days by weekday
        var result: [[HeatmapDay]] = Array(repeating: [], count: 7)

        for day in days {
            if let date = dateFromString(day.date) {
                let weekday = Calendar.current.component(.weekday, from: date)
                let index = (weekday + 5) % 7 // Convert to Monday = 0
                result[index].append(day)
            }
        }

        return result
    }

    private func dateFromString(_ dateStr: String) -> Date? {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter.date(from: dateStr)
    }

    private func weekdayLabel(_ weekday: Int) -> String {
        let labels = ["월", "화", "수", "목", "금", "토", "일"]
        return labels[weekday]
    }
}

