                            value: formatMinutes(day.totalMinutes)
                        )

                        Divider()

                        StatRow(
                            label: "완료율",
                            value: String(format: "%.1f%%", day.completionPercent)
                        )

                        Divider()

                        StatRow(
                            label: "강도",
                            value: "\(day.colorIntensity)/4"
                        )
                    }
                    .padding()
                    .background(Color(.secondarySystemBackground))
                    .cornerRadius(12)

                    // TODO: 실제 체크인 목록 표시
                    // CheckinListView(date: day.date)
                }
                .padding()
            }
            .navigationTitle("상세")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button("닫기") {
                        onDismiss()
                    }
                }
            }
        }
    }

    private func formatMinutes(_ minutes: Int) -> String {
        let hours = minutes / 60
        let mins = minutes % 60

        if hours > 0 {
            return "\(hours)시간 \(mins)분"
        } else {
            return "\(mins)분"
        }
    }
}

