### 2. SQLite 기반 오프라인 큐 구현

**DLSync/Sources/Storage/OfflineQueue.swift**
```swift
import Foundation
import SQLite
import CryptoKit
import DLCore
import DLDomain

/// 오프라인 큐 설정
public struct OfflineQueueConfig {
    public let dbPath: String
    public let encryptionKey: SymmetricKey // AES-256용 32바이트 키
    public let maxItems: Int
    public let maxAge: TimeInterval

    public init(
        dbPath: String,
        encryptionKey: SymmetricKey,
        maxItems: Int = 1000,
        maxAge: TimeInterval = 30 * 24 * 60 * 60 // 30일
    ) {
        self.dbPath = dbPath
        self.encryptionKey = encryptionKey
        self.maxItems = maxItems
        self.maxAge = maxAge
    }
}

/// 큐 아이템 상태
public enum SyncStatus: String, Codable {
    case pending
    case syncing
    case synced
    case failed
}

/// 오프라인 큐 아이템
public struct OfflineQueueItem: Identifiable, Codable {
    public let id: UUID
    public let userId: UUID
    public let operationType: OperationType
    public let resourceType: ResourceType
    public let resourceId: UUID
    public let idempotencyKey: String
    public let clientTimestamp: Date
    public var syncStatus: SyncStatus
    public var retryCount: Int
    public var lastAttempt: Date?
    public var errorMessage: String?
    public let operationData: Data // 암호화된 JSON 데이터
    public let createdAt: Date
}

/// 작업 타입
public enum OperationType: String, Codable {
    case create
    case update
    case delete
}

/// 리소스 타입
public enum ResourceType: String, Codable {
    case checkin
    case category
    case tag
}

/// SQLite 기반 오프라인 큐
public final class OfflineQueue {
    private let db: Connection
    private let config: OfflineQueueConfig
    private let logger = Logger.shared

    // SQLite 테이블 정의
    private let queueTable = Table("offline_queue")
    private let id = Expression<String>("id")
    private let userId = Expression<String>("user_id")
    private let operationType = Expression<String>("operation_type")
    private let resourceType = Expression<String>("resource_type")
    private let resourceId = Expression<String>("resource_id")
    private let idempotencyKey = Expression<String>("idempotency_key")
    private let clientTimestamp = Expression<Int64>("client_timestamp")
    private let syncStatus = Expression<String>("sync_status")
    private let retryCount = Expression<Int>("retry_count")
    private let lastAttempt = Expression<Int64?>("last_attempt")
    private let errorMessage = Expression<String?>("error_message")
    private let operationDataEncrypted = Expression<Blob>("operation_data_encrypted")
    private let createdAt = Expression<Int64>("created_at")

    public init(config: OfflineQueueConfig) throws {
        self.config = config
        self.db = try Connection(config.dbPath)
        try initSchema()
    }

    /// 스키마 초기화
    private func initSchema() throws {
        try db.run(queueTable.create(ifNotExists: true) { t in
            t.column(id, primaryKey: true)
            t.column(userId)
            t.column(operationType)
            t.column(resourceType)
            t.column(resourceId)
            t.column(idempotencyKey, unique: true)
            t.column(clientTimestamp)
            t.column(syncStatus, defaultValue: SyncStatus.pending.rawValue)
            t.column(retryCount, defaultValue: 0)
            t.column(lastAttempt)
            t.column(errorMessage)
            t.column(operationDataEncrypted)
            t.column(createdAt)
        })

        // 인덱스 생성
        try db.run(queueTable.createIndex(userId, ifNotExists: true))
        try db.run(queueTable.createIndex(syncStatus, ifNotExists: true))
        try db.run(queueTable.createIndex(createdAt, ifNotExists: true))
        try db.run(queueTable.createIndex([userId, syncStatus], ifNotExists: true))

        logger.info("Offline queue schema initialized at \(config.dbPath)")
    }

    /// AES-256-GCM으로 데이터 암호화
    private func encrypt(_ data: Data) throws -> Data {
        let nonce = AES.GCM.Nonce()
        let sealedBox = try AES.GCM.seal(data, using: config.encryptionKey, nonce: nonce)
        // Nonce + Ciphertext + Tag 결합
        return sealedBox.combined!
    }

    /// AES-256-GCM으로 데이터 복호화
    private func decrypt(_ encryptedData: Data) throws -> Data {
        let sealedBox = try AES.GCM.SealedBox(combined: encryptedData)
        return try AES.GCM.open(sealedBox, using: config.encryptionKey)
    }

    /// 큐에 작업 추가
    public func enqueue<T: Encodable>(
        userId: UUID,
        operationType: OperationType,
        resourceType: ResourceType,
        resourceId: UUID,
        data: T
    ) throws -> OfflineQueueItem {
        // 자동 정리
        try pruneIfNeeded()

        // 작업 데이터 직렬화 및 암호화
        let jsonData = try JSONEncoder().encode(data)
        let encryptedData = try encrypt(jsonData)

        let item = OfflineQueueItem(
            id: UUID(),
            userId: userId,
            operationType: operationType,
            resourceType: resourceType,
            resourceId: resourceId,
            idempotencyKey: "\(userId.uuidString)-\(resourceId.uuidString)-\(Date().timeIntervalSince1970)",
            clientTimestamp: Date(),
            syncStatus: .pending,
            retryCount: 0,
            lastAttempt: nil,
            errorMessage: nil,
            operationData: encryptedData,
            createdAt: Date()
        )

        try db.run(queueTable.insert(
            id <- item.id.uuidString,
            userId <- item.userId.uuidString,
            operationType <- item.operationType.rawValue,
            resourceType <- item.resourceType.rawValue,
            resourceId <- item.resourceId.uuidString,
            idempotencyKey <- item.idempotencyKey,
            clientTimestamp <- Int64(item.clientTimestamp.timeIntervalSince1970),
            syncStatus <- item.syncStatus.rawValue,
            retryCount <- item.retryCount,
            operationDataEncrypted <- Blob(bytes: [UInt8](encryptedData)),
            createdAt <- Int64(item.createdAt.timeIntervalSince1970)
        ))

        logger.info("Item enqueued: \(item.id) for user \(userId)")
        return item
    }

    /// 대기중인 작업 조회 (FIFO 순서)
    public func dequeuePending(userId: UUID, limit: Int = 50) throws -> [OfflineQueueItem] {
        let query = queueTable
            .filter(self.userId == userId.uuidString && self.syncStatus == SyncStatus.pending.rawValue)
            .order(createdAt.asc)
            .limit(limit)

        var items: [OfflineQueueItem] = []

        for row in try db.prepare(query) {
            guard let itemId = UUID(uuidString: row[id]),
                  let itemUserId = UUID(uuidString: row[self.userId]),
                  let itemResourceId = UUID(uuidString: row[resourceId]),
                  let opType = OperationType(rawValue: row[operationType]),
                  let resType = ResourceType(rawValue: row[resourceType]),
                  let status = SyncStatus(rawValue: row[syncStatus]) else {
                continue
            }

            let encryptedData = Data(row[operationDataEncrypted].bytes)

            let item = OfflineQueueItem(
                id: itemId,
                userId: itemUserId,
                operationType: opType,
                resourceType: resType,
                resourceId: itemResourceId,
                idempotencyKey: row[idempotencyKey],
                clientTimestamp: Date(timeIntervalSince1970: TimeInterval(row[clientTimestamp])),
                syncStatus: status,
                retryCount: row[retryCount],
                lastAttempt: row[lastAttempt].map { Date(timeIntervalSince1970: TimeInterval($0)) },
                errorMessage: row[errorMessage],
                operationData: encryptedData,
                createdAt: Date(timeIntervalSince1970: TimeInterval(row[createdAt]))
            )

            items.append(item)
        }

        return items
    }

    /// 아이템 상태 업데이트
    public func updateStatus(
        itemId: UUID,
        status: SyncStatus,
        errorMessage: String? = nil
    ) throws {
        let item = queueTable.filter(id == itemId.uuidString)

        var setters: [Setter] = [
            syncStatus <- status.rawValue,
            retryCount <- retryCount + 1,
            lastAttempt <- Int64(Date().timeIntervalSince1970)
        ]

        if let error = errorMessage {
            setters.append(self.errorMessage <- error)
        }

        try db.run(item.update(setters))
        logger.debug("Updated item \(itemId) status to \(status.rawValue)")
    }

    /// 성공한 아이템 삭제
    public func deleteSynced(itemId: UUID) throws {
        let item = queueTable.filter(id == itemId.uuidString && syncStatus == SyncStatus.synced.rawValue)
        try db.run(item.delete())
        logger.debug("Deleted synced item \(itemId)")
    }

    /// 아이템 개수 조회
    public func count(userId: UUID) throws -> Int {
        return try db.scalar(queueTable.filter(self.userId == userId.uuidString).count)
    }

    /// 자동 정리 (용량 및 시간 제한)
    private func pruneIfNeeded() throws {
        let now = Date()
        let cutoffTime = now.timeIntervalSince1970 - config.maxAge

        // 오래된 아이템 삭제
        try db.run(queueTable.filter(createdAt < Int64(cutoffTime)).delete())

        // 최대 용량 초과 시 오래된 아이템 삭제
        let totalCount = try db.scalar(queueTable.count)
        if totalCount > config.maxItems {
            let excess = totalCount - config.maxItems
            let oldestItems = queueTable.order(createdAt.asc).limit(excess)

            for row in try db.prepare(oldestItems) {
                try db.run(queueTable.filter(id == row[id]).delete())
            }

            logger.warn("Pruned \(excess) excess items from queue")
        }
    }

    /// 아이템의 작업 데이터 복호화
    public func decryptOperationData<T: Decodable>(_ item: OfflineQueueItem) throws -> T {
        let decryptedData = try decrypt(item.operationData)
        return try JSONDecoder().decode(T.self, from: decryptedData)
    }

    /// 큐 통계 조회
    public func getStats(userId: UUID) throws -> QueueStats {
        let userQueue = queueTable.filter(self.userId == userId.uuidString)

        let total = try db.scalar(userQueue.count)
        let pending = try db.scalar(userQueue.filter(syncStatus == SyncStatus.pending.rawValue).count)
        let failed = try db.scalar(userQueue.filter(syncStatus == SyncStatus.failed.rawValue).count)

        return QueueStats(total: total, pending: pending, syncing: 0, failed: failed)
    }
}

/// 큐 통계
public struct QueueStats {
    public let total: Int
    public let pending: Int
    public let syncing: Int
    public let failed: Int
}
