### 3. SyncManager 구현 (동기화 조율자)

**DLSync/Sources/SyncManager.swift**
```swift
import Foundation
import Combine
import DLCore
import DLDomain
import DLData
import DLNetworking

/// 동기화 상태
public enum SyncState {
    case idle
    case syncing
    case success
    case failed(Error)
}

/// 동기화 매니저
@MainActor
public final class SyncManager: ObservableObject {
    @Published public private(set) var syncState: SyncState = .idle
    @Published public private(set) var isSyncing: Bool = false
    @Published public private(set) var pendingCount: Int = 0

    private let offlineQueue: OfflineQueue
    private let syncEngine: SyncEngine
    private let networkMonitor: NetworkMonitor
    private let logger = Logger.shared

    private var cancellables = Set<AnyCancellable>()
    private var autoSyncTask: Task<Void, Never>?

    public init(
        offlineQueue: OfflineQueue,
        syncEngine: SyncEngine,
        networkMonitor: NetworkMonitor
    ) {
        self.offlineQueue = offlineQueue
        self.syncEngine = syncEngine
        self.networkMonitor = networkMonitor

        setupAutoSync()
    }

    /// 자동 동기화 설정
    private func setupAutoSync() {
        // 네트워크 상태 변화 모니터링
        networkMonitor.$isConnected
            .removeDuplicates()
            .sink { [weak self] isConnected in
                if isConnected {
                    Task { @MainActor in
                        await self?.syncIfNeeded()
                    }
                }
            }
            .store(in: &cancellables)
    }

    /// 필요 시 동기화
    public func syncIfNeeded() async {
        guard !isSyncing else { return }
        guard networkMonitor.isConnected else {
            logger.info("Skipping sync - network offline")
            return
        }

        do {
            let userId = try await getCurrentUserId()
            let pending = try offlineQueue.count(userId: userId)

            guard pending > 0 else {
                logger.info("No pending items to sync")
                return
            }

            await sync()
        } catch {
            logger.error("Failed to check pending count: \(error)")
        }
    }

    /// 강제 동기화
    public func sync() async {
        guard !isSyncing else {
            logger.warn("Sync already in progress")
            return
        }

        isSyncing = true
        syncState = .syncing

        do {
            let userId = try await getCurrentUserId()

            // 대기중인 작업 조회
            let items = try offlineQueue.dequeuePending(userId: userId, limit: 50)
            pendingCount = items.count

            guard !items.isEmpty else {
                logger.info("No pending items to sync")
                isSyncing = false
                syncState = .idle
                return
            }

            logger.info("Starting sync of \(items.count) items")

            // SyncEngine으로 배치 동기화
            let result = await syncEngine.syncBatch(items: items, offlineQueue: offlineQueue)

            logger.info("Sync completed: \(result.successCount) succeeded, \(result.failedCount) failed, \(result.conflictCount) conflicts")

            // 성공한 아이템 삭제
            for itemId in result.succeededIds {
                try offlineQueue.deleteSynced(itemId: itemId)
            }

            // 남은 pending 개수 업데이트
            pendingCount = try offlineQueue.count(userId: userId)

            syncState = .success
        } catch {
            logger.error("Sync failed: \(error)")
            syncState = .failed(error)
        }

        isSyncing = false
    }

    /// 현재 사용자 ID 가져오기
    private func getCurrentUserId() async throws -> UUID {
        // AuthService에서 현재 사용자 가져오기
        guard let user = try await AuthService.shared.currentUser() else {
            throw AppError.unauthorized
        }
        return user.id
    }

    deinit {
        autoSyncTask?.cancel()
    }
}
