### 4. SyncEngine 구현 (배치 동기화 및 충돌 해결)

**DLSync/Sources/SyncEngine.swift**
```swift
import Foundation
import DLCore
import DLDomain
import DLNetworking

/// 동기화 결과
public struct SyncBatchResult {
    public let successCount: Int
    public let failedCount: Int
    public let conflictCount: Int
    public let succeededIds: [UUID]
    public let failedIds: [UUID]
}

/// 동기화 엔진
public actor SyncEngine {
    private let apiClient: APIClient
    private let conflictResolver: ConflictResolver
    private let logger = Logger.shared

    public init(apiClient: APIClient, conflictResolver: ConflictResolver) {
        self.apiClient = apiClient
        self.conflictResolver = conflictResolver
    }

    /// 배치 동기화 실행
    public func syncBatch(
        items: [OfflineQueueItem],
        offlineQueue: OfflineQueue
    ) async -> SyncBatchResult {
        var successCount = 0
        var failedCount = 0
        var conflictCount = 0
        var succeededIds: [UUID] = []
        var failedIds: [UUID] = []

        // 배치로 API 요청 준비
        var operations: [SyncOperationData] = []

        for item in items {
            do {
                let operationData = SyncOperationData(
                    idempotencyKey: item.idempotencyKey,
                    operationType: item.operationType.rawValue,
                    resourceType: item.resourceType.rawValue,
                    resourceId: item.resourceId,
                    clientTimestamp: item.clientTimestamp,
                    data: item.operationData
                )
                operations.append(operationData)
            } catch {
                logger.error("Failed to prepare operation \(item.id): \(error)")
                failedCount += 1
                failedIds.append(item.id)
            }
        }

        // 배치 동기화 API 호출
        let request = SyncBatchRequest(
            deviceId: await DeviceInfo.deviceId,
            clientVersion: AppConstants.appVersion,
            platform: "ios",
            lastSyncAt: nil, // TODO: 마지막 동기화 시간 추적
            operations: operations
        )

        do {
            let response: SyncBatchResponse = try await apiClient.request(
                endpoint: .syncBatch,
                method: .post,
                body: request
            )

            // 결과 처리
            for (index, result) in response.results.enumerated() {
                let item = items[index]

                switch result.status {
                case "success":
                    try offlineQueue.updateStatus(itemId: item.id, status: .synced)
                    successCount += 1
                    succeededIds.append(item.id)

                case "failed":
                    try offlineQueue.updateStatus(
                        itemId: item.id,
                        status: .failed,
                        errorMessage: result.error
                    )
                    failedCount += 1
                    failedIds.append(item.id)

                case "conflicted":
                    // Last Write Wins 전략으로 충돌 해결
                    let resolved = await conflictResolver.resolveConflict(
                        item: item,
                        conflictInfo: result.conflictInfo
                    )

                    if resolved {
                        try offlineQueue.updateStatus(itemId: item.id, status: .synced)
                        successCount += 1
                        succeededIds.append(item.id)
                    } else {
                        try offlineQueue.updateStatus(
                            itemId: item.id,
                            status: .failed,
                            errorMessage: "Conflict resolution failed"
                        )
                        conflictCount += 1
                        failedIds.append(item.id)
                    }

                default:
                    logger.warn("Unknown sync status: \(result.status)")
                }
            }

            // 서버 변경사항 처리
            if !response.serverChanges.isEmpty {
                await processServerChanges(response.serverChanges)
            }

        } catch {
            logger.error("Batch sync failed: \(error)")
            // 모든 아이템을 실패로 마킹
            for item in items {
                try? offlineQueue.updateStatus(
                    itemId: item.id,
                    status: .failed,
                    errorMessage: error.localizedDescription
                )
                failedCount += 1
                failedIds.append(item.id)
            }
        }

        return SyncBatchResult(
            successCount: successCount,
            failedCount: failedCount,
            conflictCount: conflictCount,
            succeededIds: succeededIds,
            failedIds: failedIds
        )
    }

    /// 서버 변경사항 처리
    private func processServerChanges(_ changes: [ServerChange]) async {
        logger.info("Processing \(changes.count) server changes")

        for change in changes {
            // TODO: 로컬 데이터베이스에 서버 변경사항 반영
            // Repository를 통해 업데이트
        }
    }
}

/// 동기화 작업 데이터
struct SyncOperationData: Codable {
    let idempotencyKey: String
    let operationType: String
    let resourceType: String
    let resourceId: UUID
    let clientTimestamp: Date
    let data: Data
}

/// 동기화 배치 요청
struct SyncBatchRequest: Codable {
    let deviceId: String
    let clientVersion: String
    let platform: String
    let lastSyncAt: Date?
    let operations: [SyncOperationData]
}

/// 동기화 배치 응답
struct SyncBatchResponse: Codable {
    let success: Bool
    let syncedAt: Date
    let results: [SyncOperationResult]
    let serverChanges: [ServerChange]
    let hasMoreChanges: Bool
    let conflictsCount: Int
    let successCount: Int
    let failureCount: Int
}

/// 동기화 작업 결과
struct SyncOperationResult: Codable {
    let idempotencyKey: String
    let resourceId: UUID
    let status: String
    let error: String?
    let conflictInfo: ConflictInfo?
    let resolutionStrategy: String?
}

/// 서버 변경사항
struct ServerChange: Codable {
    let operationType: String
    let resourceType: String
    let resourceId: UUID
    let data: Data
    let serverTimestamp: Date
}

/// 충돌 정보
struct ConflictInfo: Codable {
    let clientVersion: Int?
    let serverVersion: Int
    let clientTimestamp: Date
    let serverTimestamp: Date
    let conflictType: String
}
