### 5. ConflictResolver 구현 (Last Write Wins 전략)

**DLSync/Sources/ConflictResolver.swift**
```swift
import Foundation
import DLCore

/// 충돌 해결 전략
public enum ConflictResolutionStrategy {
    case lastWriteWins // 최신 쓰기가 이김
    case clientWins // 클라이언트 우선
    case serverWins // 서버 우선
    case manual // 수동 해결
}

/// 충돌 해결자
public actor ConflictResolver {
    private let strategy: ConflictResolutionStrategy
    private let logger = Logger.shared

    public init(strategy: ConflictResolutionStrategy = .lastWriteWins) {
        self.strategy = strategy
    }

    /// 충돌 해결
    public func resolveConflict(
        item: OfflineQueueItem,
        conflictInfo: ConflictInfo?
    ) async -> Bool {
        guard let conflict = conflictInfo else {
            logger.warn("No conflict info provided for item \(item.id)")
            return false
        }

        switch strategy {
        case .lastWriteWins:
            return await resolveLastWriteWins(item: item, conflict: conflict)

        case .clientWins:
            return await resolveClientWins(item: item, conflict: conflict)

        case .serverWins:
            return await resolveServerWins(item: item, conflict: conflict)

        case .manual:
            // 수동 해결은 UI를 통해 처리
            logger.info("Manual conflict resolution required for item \(item.id)")
            return false
        }
    }

    /// Last Write Wins 전략
    private func resolveLastWriteWins(
        item: OfflineQueueItem,
        conflict: ConflictInfo
    ) async -> Bool {
        // 클라이언트 타임스탬프와 서버 타임스탬프 비교
        if item.clientTimestamp > conflict.serverTimestamp {
            logger.info("Client timestamp (\(item.clientTimestamp)) is newer than server (\(conflict.serverTimestamp)). Client wins.")
            return true // 클라이언트가 최신이므로 작업 진행
        } else {
            logger.info("Server timestamp (\(conflict.serverTimestamp)) is newer than client (\(item.clientTimestamp)). Server wins.")
            return false // 서버가 최신이므로 클라이언트 작업 버림
        }
    }

    /// 클라이언트 우선 전략
    private func resolveClientWins(
        item: OfflineQueueItem,
        conflict: ConflictInfo
    ) async -> Bool {
        logger.info("Resolving conflict with client wins strategy for item \(item.id)")
        return true
    }

    /// 서버 우선 전략
    private func resolveServerWins(
        item: OfflineQueueItem,
        conflict: ConflictInfo
    ) async -> Bool {
        logger.info("Resolving conflict with server wins strategy for item \(item.id)")
        return false
    }
}
