```swift
import Foundation
import BackgroundTasks
import DLCore

/// 백그라운드 동기화 태스크
public final class BackgroundSyncTask {
    public static let taskIdentifier = "com.donelist.sync.background"

    private let syncManager: SyncManager
    private let logger = Logger.shared

    public init(syncManager: SyncManager) {
        self.syncManager = syncManager
    }

    /// 백그라운드 태스크 등록
    public func register() {
        BGTaskScheduler.shared.register(
            forTaskWithIdentifier: Self.taskIdentifier,
            using: nil
        ) { [weak self] task in
            self?.handleBackgroundSync(task: task as! BGAppRefreshTask)
        }

        logger.info("Background sync task registered")
    }

    /// 백그라운드 태스크 스케줄링
    public func schedule() {
        let request = BGAppRefreshTaskRequest(identifier: Self.taskIdentifier)
        request.earliestBeginDate = Date(timeIntervalSinceNow: 15 * 60) // 15분 후

        do {
            try BGTaskScheduler.shared.submit(request)
            logger.info("Background sync task scheduled")
        } catch {
            logger.error("Failed to schedule background sync: \(error)")
        }
    }

    /// 백그라운드 동기화 처리
    private func handleBackgroundSync(task: BGAppRefreshTask) {
        logger.info("Background sync task started")

        // 태스크 만료 핸들러
        task.expirationHandler = {
            self.logger.warn("Background sync task expired")
            task.setTaskCompleted(success: false)
        }

        // 동기화 실행
        Task {
            await syncManager.sync()

            // 다음 백그라운드 태스크 스케줄링
            self.schedule()

            task.setTaskCompleted(success: true)
            self.logger.info("Background sync task completed")
        }
    }
}
```

