### 10. KeychainService 확장 (암호화 키 관리)

**DLNetworking/Sources/Security/KeychainService+EncryptionKey.swift**
```swift
import Foundation
import Security
import CryptoKit

extension KeychainService {
    private static let encryptionKeyIdentifier = "com.donelist.offline.encryptionKey"

    /// 암호화 키 가져오기 또는 생성
    public func getOrCreateEncryptionKey() -> SymmetricKey {
        if let existingKey = getEncryptionKey() {
            return existingKey
        }

        // 새 키 생성
        let newKey = SymmetricKey(size: .bits256)
        saveEncryptionKey(newKey)
        return newKey
    }

    /// 암호화 키 저장
    private func saveEncryptionKey(_ key: SymmetricKey) {
        let keyData = key.withUnsafeBytes { Data($0) }

        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrAccount as String: Self.encryptionKeyIdentifier,
            kSecValueData as String: keyData,
            kSecAttrAccessible as String: kSecAttrAccessibleAfterFirstUnlock
        ]

        SecItemDelete(query as CFDictionary)
        SecItemAdd(query as CFDictionary, nil)
    }

    /// 암호화 키 가져오기
    private func getEncryptionKey() -> SymmetricKey? {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrAccount as String: Self.encryptionKeyIdentifier,
            kSecReturnData as String: true
        ]

        var result: AnyObject?
        let status = SecItemCopyMatching(query as CFDictionary, &result)

        guard status == errSecSuccess,
              let keyData = result as? Data else {
            return nil
        }

        return SymmetricKey(data: keyData)
    }
}
```

