### 2. APNs 토큰 관리 및 등록

**DLNotifications/Sources/APNsTokenManager.swift**
```swift
import Foundation
import UserNotifications
import DLCore
import DLNetworking

/// APNs 디바이스 토큰 관리자
@MainActor
public final class APNsTokenManager: ObservableObject {
    @Published public private(set) var deviceToken: String?
    @Published public private(set) var authorizationStatus: UNAuthorizationStatus = .notDetermined

    private let apiClient: APIClient
    private let logger: Logger
    private let keychain: KeychainService

    private let deviceTokenKey = "com.donelist.apns.deviceToken"

    public init(
        apiClient: APIClient,
        logger: Logger,
        keychain: KeychainService = .shared
    ) {
        self.apiClient = apiClient
        self.logger = logger
        self.keychain = keychain

        // 저장된 토큰 로드
        self.deviceToken = keychain.getString(deviceTokenKey)
    }

    // MARK: - Permission Request

    /// 푸시 알림 권한 요청
    public func requestAuthorization() async throws {
        let center = UNUserNotificationCenter.current()

        let granted = try await center.requestAuthorization(options: [
            .alert, .badge, .sound, .providesAppNotificationSettings
        ])

        if granted {
            logger.info("Push notification permission granted")
            await checkAuthorizationStatus()
            await registerForRemoteNotifications()
        } else {
            logger.warning("Push notification permission denied")
            authorizationStatus = .denied
        }
    }

    /// 현재 권한 상태 확인
    public func checkAuthorizationStatus() async {
        let center = UNUserNotificationCenter.current()
        let settings = await center.notificationSettings()
        authorizationStatus = settings.authorizationStatus

        logger.info("Notification authorization status: \(settings.authorizationStatus.rawValue)")
    }

    // MARK: - Device Token Management

    /// 원격 알림 등록 요청 (UIApplication에서 호출)
    public func registerForRemoteNotifications() async {
        await UIApplication.shared.registerForRemoteNotifications()
    }

    /// APNs에서 받은 디바이스 토큰 저장 및 서버 등록
    public func didRegisterForRemoteNotifications(deviceToken: Data) async {
        let tokenString = deviceToken.map { String(format: "%02.2hhx", $0) }.joined()

        self.deviceToken = tokenString
        keychain.setString(tokenString, forKey: deviceTokenKey)

        logger.info("APNs device token received: \(tokenString)")

        // 서버에 디바이스 토큰 등록
        await registerTokenWithServer(tokenString)
    }

    /// APNs 등록 실패 처리
    public func didFailToRegisterForRemoteNotifications(error: Error) {
        logger.error("Failed to register for remote notifications: \(error.localizedDescription)")
    }

    // MARK: - Server Registration

    /// 서버에 디바이스 토큰 등록
    private func registerTokenWithServer(_ token: String) async {
        do {
            let request = RegisterDeviceTokenRequest(
                deviceToken: token,
                platform: "ios"
            )

            try await apiClient.request(
                endpoint: .registerDeviceToken,
                method: .post,
                body: request
            )

            logger.info("Device token registered with server successfully")
        } catch {
            logger.error("Failed to register device token with server: \(error.localizedDescription)")
        }
    }

    /// 서버에서 디바이스 토큰 제거
    public func unregisterTokenFromServer() async {
        guard let token = deviceToken else { return }

        do {
            try await apiClient.request(
                endpoint: .unregisterDeviceToken(token),
                method: .delete
            )

            logger.info("Device token unregistered from server")
        } catch {
            logger.error("Failed to unregister device token: \(error.localizedDescription)")
        }
    }
}

// MARK: - API Models

struct RegisterDeviceTokenRequest: Encodable {
    let deviceToken: String
    let platform: String
}
```

