    @Published public private(set) var badgeCount: Int = 0

    private let logger: Logger
    private let deepLinkRouter: DeepLinkRouter

    public init(
        logger: Logger,
        deepLinkRouter: DeepLinkRouter
    ) {
        self.logger = logger
        self.deepLinkRouter = deepLinkRouter
        super.init()

        UNUserNotificationCenter.current().delegate = self
    }

    // MARK: - Badge Management

    /// 배지 카운트 업데이트
    public func updateBadgeCount(_ count: Int) async {
        badgeCount = count
        await UIApplication.shared.setApplicationIconBadgeNumber(count)
    }

    /// 배지 초기화
    public func clearBadge() async {
        await updateBadgeCount(0)
    }

    // MARK: - Notification Actions

    /// 알림 카테고리 및 액션 등록
    public func registerNotificationCategories() async {
        let checkinAction = UNNotificationAction(
            identifier: "CHECKIN_ACTION",
            title: "체크인하기",
            options: [.foreground]
        )

        let snoozeAction = UNNotificationAction(
            identifier: "SNOOZE_ACTION",
            title: "15분 후 다시 알림",
            options: []
        )

        let checkinCategory = UNNotificationCategory(
            identifier: "CHECKIN_REMINDER",
            actions: [checkinAction, snoozeAction],
            intentIdentifiers: [],
            options: []
        )

        let center = UNUserNotificationCenter.current()
        center.setNotificationCategories([checkinCategory])

        logger.info("Notification categories registered")
