}

// MARK: - UNUserNotificationCenterDelegate

extension NotificationService: UNUserNotificationCenterDelegate {
    /// 포그라운드 알림 수신 처리
    public func userNotificationCenter(
        _ center: UNUserNotificationCenter,
        willPresent notification: UNNotification
    ) async -> UNNotificationPresentationOptions {
        logger.info("Received notification in foreground: \(notification.request.identifier)")

        let userInfo = notification.request.content.userInfo
        processNotification(userInfo: userInfo)

        // 포그라운드에서도 배너, 사운드, 배지 표시
        return [.banner, .sound, .badge]
    }

    /// 알림 탭 처리
    public func userNotificationCenter(
        _ center: UNUserNotificationCenter,
        didReceive response: UNNotificationResponse
    ) async {
        let userInfo = response.notification.request.content.userInfo
        let actionIdentifier = response.actionIdentifier

        logger.info("User responded to notification: \(actionIdentifier)")

        switch actionIdentifier {
        case UNNotificationDefaultActionIdentifier:
            // 알림 탭 - Deep Link 처리
            processNotificationTap(userInfo: userInfo)

        case "CHECKIN_ACTION":
            // 체크인 액션
            await handleCheckinAction()

        case "SNOOZE_ACTION":
            // 스누즈 액션
            await handleSnoozeAction()

        default:
            break
        }
    }

    // MARK: - Private Helpers

    private func processNotification(userInfo: [AnyHashable: Any]) {
        guard let notificationData = parseNotification(userInfo: userInfo) else {
            logger.warning("Failed to parse notification")
            return
        }

        receivedNotifications.append(notificationData)
    }

    private func processNotificationTap(userInfo: [AnyHashable: Any]) {
        guard let deepLink = userInfo["deepLink"] as? String else {
            logger.info("No deep link in notification")
            return
        }

        deepLinkRouter.handle(deepLink: deepLink)
    }

    private func parseNotification(userInfo: [AnyHashable: Any]) -> DLNotification? {
        // Parse notification payload
        guard let aps = userInfo["aps"] as? [String: Any] else { return nil }

        let alert = aps["alert"] as? [String: Any]
        let title = alert?["title"] as? String ?? ""
        let body = alert?["body"] as? String ?? ""

        let type = userInfo["type"] as? String ?? "unknown"
        let deepLink = userInfo["deepLink"] as? String

        return DLNotification(
            id: UUID().uuidString,
            type: type,
            title: title,
            body: body,
            deepLink: deepLink,
            receivedAt: Date()
        )
    }

    private func handleCheckinAction() async {
        logger.info("Checkin action triggered from notification")
        deepLinkRouter.handle(deepLink: "donelist://checkin")
    }

    private func handleSnoozeAction() async {
        logger.info("Snooze action triggered")
        // Schedule local notification 15 minutes later
        let content = UNMutableNotificationContent()
        content.title = "체크인 알림"
        content.body = "체크인할 시간입니다!"
        content.sound = .default
        content.categoryIdentifier = "CHECKIN_REMINDER"

        let trigger = UNTimeIntervalNotificationTrigger(
            timeInterval: 15 * 60,
            repeats: false
        )

        let request = UNNotificationRequest(
            identifier: UUID().uuidString,
            content: content,
            trigger: trigger
        )

        try? await UNUserNotificationCenter.current().add(request)
    }
}

// MARK: - Models

public struct DLNotification: Identifiable, Codable {
    public let id: String
    public let type: String
    public let title: String
    public let body: String
    public let deepLink: String?
    public let receivedAt: Date
}
