**DLNotifications/Sources/DeepLinkRouter.swift**
```swift
import Foundation
import SwiftUI
import DLCore

/// Deep Link 라우팅 처리
@MainActor
public final class DeepLinkRouter: ObservableObject {
    @Published public var activeRoute: DeepLinkRoute?

    private let logger: Logger

    public init(logger: Logger) {
        self.logger = logger
    }

    /// Deep Link 처리
    public func handle(deepLink: String) {
        guard let url = URL(string: deepLink) else {
            logger.warning("Invalid deep link: \(deepLink)")
            return
        }

        logger.info("Handling deep link: \(deepLink)")

        let route = parseDeepLink(url: url)
        activeRoute = route
    }

    /// URL을 DeepLinkRoute로 파싱
    private func parseDeepLink(url: URL) -> DeepLinkRoute? {
        guard url.scheme == "donelist" else { return nil }

        switch url.host {
        case "checkin":
            return .checkin

        case "task":
            if let taskID = url.pathComponents.last {
                return .task(id: taskID)
            }

        case "calendar":
            if let dateString = url.pathComponents.last,
               let date = ISO8601DateFormatter().date(from: dateString) {
                return .calendarDay(date: date)
            }

        case "settings":
            if url.path == "/notifications" {
                return .notificationSettings
            }
            return .settings

        default:
            break
        }

        return nil
    }

    /// Deep Link 초기화
    public func clearActiveRoute() {
        activeRoute = nil
    }
}

// MARK: - DeepLinkRoute

public enum DeepLinkRoute: Equatable {
    case checkin
    case task(id: String)
    case calendarDay(date: Date)
    case settings
    case notificationSettings
}
