```swift
import Foundation
import UserNotifications
import DLCore
import DLNetworking
import DLDomain

@MainActor
public final class NotificationSettingsViewModel: ObservableObject {
    @Published public var authorizationStatus: UNAuthorizationStatus = .notDetermined
    @Published public var checkinRemindersEnabled = true
    @Published public var subscriptionNotificationsEnabled = true
    @Published public var systemAlertsEnabled = true
    @Published public var dndEnabled = false
    @Published public var dndStartTime = Calendar.current.date(from: DateComponents(hour: 22, minute: 0))!
    @Published public var dndEndTime = Calendar.current.date(from: DateComponents(hour: 8, minute: 0))!
    @Published public var badgeEnabled = true
    @Published public var showError = false
    @Published public var errorMessage: String?

    private let apiClient: APIClient
    private let logger: Logger

    public var permissionStatusText: String {
        switch authorizationStatus {
        case .authorized: return "허용됨"
        case .denied: return "거부됨"
        case .notDetermined: return "설정 안함"
        case .provisional: return "임시 허용"
        case .ephemeral: return "임시"
        @unknown default: return "알 수 없음"
        }
    }

    public init(apiClient: APIClient, logger: Logger) {
        self.apiClient = apiClient
        self.logger = logger
    }

    // MARK: - Actions

    public func loadSettings() async {
        await checkAuthorizationStatus()
        await fetchSettingsFromServer()
    }

    public func updateSettings() async {
        do {
            let settings = NotificationSettings(
                checkinReminders: checkinRemindersEnabled,
                subscriptionNotifications: subscriptionNotificationsEnabled,
                systemAlerts: systemAlertsEnabled,
                dndEnabled: dndEnabled,
                dndStartTime: formatTime(dndStartTime),
                dndEndTime: formatTime(dndEndTime),
                badgeEnabled: badgeEnabled
            )

            try await apiClient.request(
                endpoint: .updateNotificationSettings,
                method: .put,
                body: settings
            )

            logger.info("Notification settings updated successfully")
        } catch {
            logger.error("Failed to update notification settings: \(error.localizedDescription)")
            errorMessage = "설정 업데이트에 실패했습니다."
            showError = true
        }
    }

    public func openAppSettings() {
        if let url = URL(string: UIApplication.openSettingsURLString) {
            UIApplication.shared.open(url)
        }
    }

    // MARK: - Private

    private func checkAuthorizationStatus() async {
        let center = UNUserNotificationCenter.current()
        let settings = await center.notificationSettings()
        authorizationStatus = settings.authorizationStatus
    }

    private func fetchSettingsFromServer() async {
        do {
            let settings: NotificationSettings = try await apiClient.request(
                endpoint: .getNotificationSettings,
                method: .get
            )

            checkinRemindersEnabled = settings.checkinReminders
            subscriptionNotificationsEnabled = settings.subscriptionNotifications
            systemAlertsEnabled = settings.systemAlerts
            dndEnabled = settings.dndEnabled
            badgeEnabled = settings.badgeEnabled

            if let startTime = parseTime(settings.dndStartTime) {
                dndStartTime = startTime
            }
            if let endTime = parseTime(settings.dndEndTime) {
                dndEndTime = endTime
            }
        } catch {
            logger.error("Failed to fetch notification settings: \(error.localizedDescription)")
        }
    }

    private func formatTime(_ date: Date) -> String {
        let formatter = DateFormatter()
        formatter.dateFormat = "HH:mm"
        return formatter.string(from: date)
    }

    private func parseTime(_ timeString: String) -> Date? {
        let formatter = DateFormatter()
        formatter.dateFormat = "HH:mm"
        return formatter.date(from: timeString)
    }
}

// MARK: - API Models

struct NotificationSettings: Codable {
    let checkinReminders: Bool
    let subscriptionNotifications: Bool
    let systemAlerts: Bool
    let dndEnabled: Bool
    let dndStartTime: String
    let dndEndTime: String
    let badgeEnabled: Bool
}
