        let deepLinkRouter = DIContainer.shared.deepLinkRouter

        tokenManager = APNsTokenManager(
            apiClient: apiClient,
            logger: logger
        )

        notificationService = NotificationService(
            logger: logger,
            deepLinkRouter: deepLinkRouter
        )

        Task {
            await notificationService.registerNotificationCategories()
        }
    }

    // MARK: - APNs Callbacks

    func application(
        _ application: UIApplication,
        didRegisterForRemoteNotificationsWithDeviceToken deviceToken: Data
    ) {
        Task {
            await tokenManager.didRegisterForRemoteNotifications(deviceToken: deviceToken)
        }
    }

    func application(
        _ application: UIApplication,
        didFailToRegisterForRemoteNotificationsWithError error: Error
    ) {
        tokenManager.didFailToRegisterForRemoteNotifications(error: error)
    }
}
