struct ContentView: View {
    @EnvironmentObject var deepLinkRouter: DeepLinkRouter
    @State private var selectedTab = 0

    var body: some View {
        TabView(selection: $selectedTab) {
            CheckinView()
                .tabItem { Label("체크인", systemImage: "checkmark.circle") }
                .tag(0)

            CalendarView()
                .tabItem { Label("캘린더", systemImage: "calendar") }
                .tag(1)

            SettingsView()
                .tabItem { Label("설정", systemImage: "gearshape") }
                .tag(2)
        }
        .onChange(of: deepLinkRouter.activeRoute) { _, route in
            handleDeepLink(route)
        }
        .sheet(item: $deepLinkRouter.activeRoute) { route in
            sheetForRoute(route)
        }
    }

    private func handleDeepLink(_ route: DeepLinkRoute?) {
        guard let route = route else { return }

        switch route {
        case .checkin:
            selectedTab = 0

        case .calendarDay:
            selectedTab = 1

        case .settings, .notificationSettings:
            selectedTab = 2

        default:
            break
        }
    }

    @ViewBuilder
    private func sheetForRoute(_ route: DeepLinkRoute) -> some View {
        switch route {
        case .task(let id):
            TaskDetailView(taskID: id)

        case .notificationSettings:
            NavigationStack {
                NotificationSettingsView(
                    viewModel: NotificationSettingsViewModel(
                        apiClient: DIContainer.shared.apiClient,
                        logger: Logger.shared
                    )
                )
            }

        default:
            EmptyView()
        }
    }
}
