#### 이미지 캐싱

**DLCore/Sources/Services/ImageCache.swift**
```swift
import SwiftUI

actor ImageCache {
    static let shared = ImageCache()

    private var cache: [URL: Image] = [:]
    private let maxCacheSize = 50 // 최대 50개 이미지

    func image(for url: URL) -> Image? {
        cache[url]
    }

    func cache(_ image: Image, for url: URL) {
        if cache.count >= maxCacheSize {
            // LRU 방식으로 오래된 항목 제거
            if let firstKey = cache.keys.first {
                cache.removeValue(forKey: firstKey)
            }
        }
        cache[url] = image
    }

    func clear() {
        cache.removeAll()
    }
}

struct AsyncCachedImage: View {
    let url: URL
    @State private var image: Image?

    var body: some View {
        Group {
            if let image = image {
                image.resizable()
            } else {
                ProgressView()
                    .task {
                        await loadImage()
                    }
            }
        }
    }

    private func loadImage() async {
        // 캐시 확인
        if let cached = await ImageCache.shared.image(for: url) {
            image = cached
            return
        }

        // 다운로드
        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            if let uiImage = UIImage(data: data) {
                let swiftUIImage = Image(uiImage: uiImage)
                await ImageCache.shared.cache(swiftUIImage, for: url)
                image = swiftUIImage
            }
        } catch {
            print("Image load failed: \(error)")
        }
    }
}
```

#### API 응답 캐싱 강화

**DLNetworking/Sources/Cache/ResponseCache.swift**
```swift
import Foundation

actor ResponseCache {
    static let shared = ResponseCache()

    private var cache: [String: CachedResponse] = [:]
    private let maxAge: TimeInterval = 300 // 5분

    struct CachedResponse {
        let data: Data
        let timestamp: Date
        let etag: String?
    }

    func get(for key: String) -> CachedResponse? {
        guard let cached = cache[key] else { return nil }

        // TTL 체크
        if Date().timeIntervalSince(cached.timestamp) > maxAge {
            cache.removeValue(forKey: key)
            return nil
        }

        return cached
    }

    func set(_ response: CachedResponse, for key: String) {
        cache[key] = response
    }

    func invalidate(matching pattern: String) {
        let keys = cache.keys.filter { $0.contains(pattern) }
        keys.forEach { cache.removeValue(forKey: $0) }
    }

    func clear() {
        cache.removeAll()
    }
}
```

**APIClient에 캐싱 로직 통합**
```swift
extension APIClientImpl {
    func requestWithCache<T: Decodable>(
        _ endpoint: Endpoint,
        cacheKey: String
    ) async throws -> T {
        // 캐시 확인
        if let cached = await ResponseCache.shared.get(for: cacheKey) {
            return try JSONDecoder().decode(T.self, from: cached.data)
        }

        // 네트워크 요청
        let response: T = try await request(endpoint)

        // 캐시 저장
        if let data = try? JSONEncoder().encode(response) {
            await ResponseCache.shared.set(
                ResponseCache.CachedResponse(
                    data: data,
                    timestamp: Date(),
                    etag: nil
                ),
                for: cacheKey
            )
        }

        return response
    }
}
```

