        mockLocalDataSource = MockCheckinLocalDataSource()
        sut = CheckinRepositoryImpl(
            remoteDataSource: mockRemoteDataSource,
            localDataSource: mockLocalDataSource
        )
    }

    func testCreate_SavesLocallyFirst() async throws {
        // Given
        let checkin = Checkin.mock()
        mockLocalDataSource.saveResult = .success(())
        mockRemoteDataSource.createResult = .success(CheckinDTO.mock())

        // When
        _ = try await sut.create(checkin)

        // Then
        XCTAssertEqual(mockLocalDataSource.saveCallCount, 1)
        XCTAssertEqual(mockRemoteDataSource.createCallCount, 1)
    }
}
